165	export type WeatherKind = "clear" | "rain" | "snow";
166	export type WeatherState = { kind: WeatherKind; intensity: number };
167	
168	/**
169	 * An in-progress village raid — session-only, never serialized (like the boss).
170	 * A reload cancels it. Waves of raiders spawn around `center`; once a wave is
171	 * cleared, `waveTimer` counts down to the next, until all `totalWaves` are beaten.
172	 */
173	export type RaidState = {
174	  center: { x: number; z: number };
175	  /** Waves spawned so far (0 before the first spawns, up to totalWaves). */
176	  wavesSpawned: number;
177	  totalWaves: number;
178	  /** Seconds until the next wave once the current one is cleared. */
179	  waveTimer: number;
180	};
181	
182	export type GameState = {
183	  world: VoxelWorld;
184	  blockChanges: BlockChangeTracker;
185	  player: PlayerState;
186	  inventory: InventorySlot[];
187	  equippedArmor: EquippedArmor;
188	  selectedSlot: number;
189	  /** Current game mode. Persisted (save v8); switchable in-game via setGameMode. */
190	  gameMode: GameMode;
191	  /** Current difficulty. Persisted (save v9); switchable in-game via setDifficulty. */
192	  difficulty: Difficulty;
193	  /** Hardcore world: forces Survival + Hard, locks both switchers, permadeath. Persisted (save v10); immutable. */
194	  hardcore: boolean;
195	  /** True once a hardcore run has ended in death — drives the spectator dead-world + Game Over screen. Persisted (save v10). */
196	  gameOver: boolean;
197	  /** True while flying (Creative toggle, always on for Spectator). Session-only, never serialized. */
198	  isFlying: boolean;
199	  hearts: number;
200	  hunger: number;
201	  /** Remaining breath, 0..MAX_OXYGEN. Session-only; refills out of water. */
202	  oxygen: number;
203	  /** Active status effects → remaining seconds. Persisted (save v6); cleared on death. */
204	  effects: Map<EffectId, number>;
205	  /** Banked XP points (XP_PER_LEVEL points = 1 level). Persisted (save v7); NOT cleared on death. */
206	  xp: number;
207	  /** Gameplay statistics → running counter (blocks mined, mobs killed, time played, …). Persisted (save v13); NOT cleared on death. */
208	  stats: Map<string, number>;
209	  /** Unlocked advancement ids. Persisted (save v13); NOT cleared on death. */
210	  advancements: Set<string>;
211	  isDead: boolean;
212	  respawnTimer: number;
213	  inventoryOpen: boolean;
214	  /** True while the advancements & statistics overlay (L key) is open. Session-only. */
215	  advancementsOpen: boolean;
216	  /** Crafting station whose recipes (or the enchanting panel) are unlocked while the inventory is open, or null. */
217	  craftingStation: "furnace" | "villager" | "brewing" | "enchanting" | "anvil" | "grindstone" | null;
218	  /** The open villager's trade profession while a "villager" station is up (gates which trades show + craft), else null. Session-only. */
219	  activeVillagerProfession: Profession | null;
220	  /** Chest contents (block-entities) keyed by the block's voxel index. */
221	  containers: Map<number, InventorySlot[]>;
222	  /** Lit TNT keyed by voxel index → seconds left on its fuse (session-only, never serialized). */
223	  primedTnt: Map<number, number>;
224	  /** Voxel index of the chest open in the inventory panel, or null. */
225	  openContainerIndex: number | null;
226	  /** Worldgen dungeon chest voxel indices (session; re-derived from the seed each load). */
227	  dungeonChestIndices: Set<number>;
228	  /** Worldgen dungeon spawner voxel indices (session; re-derived from the seed each load). */
229	  dungeonSpawnerIndices: Set<number>;
230	  /** Worldgen shipwreck chest voxel indices (session; re-derived from the seed each load). */
231	  shipwreckChestIndices: Set<number>;
232	  /** Worldgen buried-treasure chest voxel indices (session; re-derived from the seed each load). */
233	  buriedTreasureChestIndices: Set<number>;
234	  /** Buried-treasure chest positions (session; re-derived) — the treasure-map compass targets the nearest unlooted one. */
235	  treasureSites: Array<{ x: number; y: number; z: number; index: number }>;
236	  /** Worldgen chests (dungeon/shipwreck/buried) already opened/broken (persisted as `lootedChests`) — gates one-time lazy loot fill. */
237	  lootedWorldgenChests: Set<number>;
238	  /** Village center (x,z) sites (session; re-derived from the seed each load) — seed the resident villager population. */
239	  villageSites: Array<{ x: number; z: number }>;
240	  /** Frozen simulation behind the pause menu; only commands are processed. */
241	  paused: boolean;
242	  debugOpen: boolean;
243	  debugInfo: DebugInfo | null;
244	  cameraMode: CameraMode;
245	  capsActive: boolean;
246	  mobs: MobState[];
247	  nextMobId: number;
248	  thrownSpears: ThrownSpearState[];
249	  nextThrownSpearId: number;
250	  /** In-flight arrows (session-only; never serialized). */
251	  projectiles: ProjectileState[];
252	  nextProjectileId: number;
253	  /** The active fishing cast, or null when not fishing (session-only). */
254	  fishing: FishingState | null;
255	  vehicles: VehicleState[];
256	  nextVehicleId: number;
257	  mountedVehicleId: number | null;
258	  dayClock: number;
259	  /** Derived from dayClock every tick; 0.04–1.0. */
260	  daylight: number;
261	  daylightPercent: number;
262	  /** Cosmetic, transient weather (never serialized). Drives precip + sky + audio. */
263	  weather: WeatherState;
264	  /** Seconds left in the sleep fade; > 0 freezes the sim until time skips. */
265	  sleepTimer: number;
266	  /** Bed respawn point (block coords), or null to respawn at a random land point. */
267	  spawnPoint: { x: number; y: number; z: number } | null;
268	  mining: MiningState;
269	  timers: GameTimers;
270	  /** Set when world geometry changed; the renderer rebuilds the mesh and clears it. */
271	  worldMeshDirty: boolean;
272	  /** True once the boss has been defeated — drives the one-shot victory screen (session-only). */
273	  victory: boolean;
274	  /** The active village raid, or null. Session-only (a reload cancels it). */
275	  raid: RaidState | null;
276	};
277	
278	export function createTimers(): GameTimers {
279	  return {
280	    voidTimer: 0,
281	    regenTimer: 0,
282	    waterExposureTimer: 0,
283	    waterDamageTimer: 0,
284	    lavaBurnTimer: 0,
285	    lavaDamageTimer: 0,
286	    drownTimer: 0,
287	    starvationTimer: 0,
288	    sprintDistanceBudget: 0,
289	    walkDistanceBudget: 0,
290	    jumpBudget: 0,
291	    effectRegenTimer: 0,
292	    effectPoisonTimer: 0,
293	    stuckTimer: 0,
294	    hostileSpawnTimer: 0,
295	    aquaticSpawnTimer: 0,
296	    spawnerTimer: 0,
297	    daylightHudTimer: 0,
298	    debugHudTimer: 0,
299	    randomTickTimer: 0,
300	    breedTimer: 0,
301	    spearThrowCooldown: 0,
302	    bowCooldownTimer: 0
303	  };
304	}
305	
306	/** Per-frame continuous input, owned by the input controller. */
307	export type FrameInput = {
308	  keys: ReadonlySet<string>;
309	  capsActive: boolean;

