1	import type { GameEngine } from "@/lib/game/engine/GameEngine";
2	import type { FrameInput } from "@/lib/game/engine/state";
3	import { FLY_DOUBLE_TAP_WINDOW_SECONDS } from "@/lib/game/config";
4	
5	const MOUSE_SENSITIVITY = 0.0021;
6	
7	type MutableInput = {
8	  keys: Set<string>;
9	  capsActive: boolean;
10	  leftMouseHeld: boolean;
11	  pointerLocked: boolean;
12	};
13	
14	export type InputController = {
15	  /** Live continuous-input view, passed to engine.step every frame. */
16	  readonly input: FrameInput;
17	  /** Drops held keys and the mouse button (on death/respawn). */
18	  clearKeys(): void;
19	  dispose(): void;
20	};
21	
22	type CreateInputControllerArgs = {
23	  /** The WebGL canvas — pointer lock target. */
24	  canvas: HTMLCanvasElement;
25	  engine: GameEngine;
26	  onResize: () => void;
27	  onLockChange: (locked: boolean) => void;
28	};
29	
30	/**
31	 * Owns every DOM listener. Continuous input (keys, mouse button, pointer
32	 * lock) is exposed as a FrameInput the engine reads each step; discrete
33	 * actions become engine commands; mouse-look goes through engine.applyLook.
34	 */
35	export function createInputController(args: CreateInputControllerArgs): InputController {
36	  const { canvas, engine, onResize, onLockChange } = args;
37	
38	  const input: MutableInput = {
39	    keys: new Set<string>(),
40	    capsActive: false,
41	    leftMouseHeld: false,
42	    pointerLocked: false
43	  };
44	
45	  const uiBlocked = () => engine.state.inventoryOpen || engine.state.advancementsOpen || engine.state.isDead || engine.state.paused;
46	
47	  // Timestamp (ms) of the last discrete Space press, for double-tap-to-fly detection.
48	  let lastSpaceTapAt = -Infinity;
49	
50	  const onMouseMove = (evt: MouseEvent) => {
51	    if (!input.pointerLocked) return;
52	    engine.applyLook(-evt.movementX * MOUSE_SENSITIVITY, -evt.movementY * MOUSE_SENSITIVITY);
53	  };
54	
55	  const onKeyDown = (evt: KeyboardEvent) => {
56	    // Escape under pointer lock never reaches us — the browser consumes it to
57	    // exit the lock, and the pointerlockchange handler below opens the menu.
58	    if (evt.code === "Escape") {
59	      if (engine.state.paused) engine.dispatch({ type: "resume" });
60	      else if (engine.state.inventoryOpen) engine.dispatch({ type: "toggleInventory" });
61	      else if (engine.state.advancementsOpen) engine.dispatch({ type: "toggleAdvancements" });
62	      else if (!input.pointerLocked) engine.dispatch({ type: "pause" });
63	      return;
64	    }
65	
66	    // Render-only and engine-supported in every state, so it works even from
67	    // the pause menu — like Minecraft's F5.
68	    if (evt.code === "KeyV") {
69	      engine.dispatch({ type: "toggleCameraView" });
70	      return;
71	    }
72	
73	    if (engine.state.paused) return;
74	
75	    if (evt.code === "F3") {
76	      evt.preventDefault();
77	      engine.dispatch({ type: "toggleDebug" });
78	      return;
79	    }
80	
81	    if (evt.code.startsWith("Digit")) {
82	      const idx = Number.parseInt(evt.code.slice(5), 10) - 1;
83	      if (idx >= 0) engine.dispatch({ type: "selectSlot", index: idx });
84	    }
85	
86	    if (evt.code === "KeyI") {
87	      engine.dispatch({ type: "toggleInventory" });
88	      input.keys.clear();
89	      if (input.pointerLocked) document.exitPointerLock();
90	      return;
91	    }
92	
93	    if (evt.code === "KeyL") {
94	      engine.dispatch({ type: "toggleAdvancements" });
95	      input.keys.clear();
96	      if (input.pointerLocked) document.exitPointerLock();
97	      return;
98	    }
99	
100	    // Shift-gated so a stray `U` can't teleport the player mid-play; the 0.8s
101	    // auto-unstuck safeguard still covers genuine wedged-in-terrain cases.
102	    if (evt.shiftKey && evt.code === "KeyU") {
103	      engine.dispatch({ type: "unstuck" });
104	      return;
105	    }
106	
107	    if (uiBlocked()) return;
108	
109	    if (evt.code === "KeyE") {
110	      evt.preventDefault();
111	      engine.dispatch({ type: "placeBlock" });
112	    }
113	    if (evt.code === "KeyF") {
114	      evt.preventDefault();
115	      // One key for consumables: a held potion is drunk for its effect, anything else is eaten.
116	      const held = engine.state.inventory[engine.state.selectedSlot];
117	      engine.dispatch({ type: held?.effect ? "drinkPotion" : "eatFood" });
118	    }
119	
120	    // Double-tap Space toggles flight (Creative/Spectator). Ignore auto-repeat
121	    // (held key) so only distinct presses count; the engine no-ops in modes
122	    // that can't fly.
