49	export function tickPlayerMotion(state: GameState, input: FrameInput, dt: number, applyDamage: (amount: number) => void): MoveTickResult {
50	  const { world, player, timers } = state;
51	  const move = input.move;
52	  // Spectator phases through terrain (noclip); Creative/Spectator fly with direct
53	  // vertical control instead of gravity.
54	  const noclip = isNoclip(state.gameMode);
55	  const flying = noclip || (state.isFlying && canFly(state.gameMode));
56	
57	  const stepAxis = (axis: "x" | "y" | "z", amount: number) => {
58	    if (noclip) {
59	      player.position[axis] += amount; // pass straight through blocks
60	      return;
61	    }
62	    const stepSize = 0.05 * Math.sign(amount);
63	    let remaining = amount;
64	    while (Math.abs(remaining) > 1e-6) {
65	      const step = Math.abs(remaining) > Math.abs(stepSize) ? stepSize : remaining;
66	      player.position[axis] += step;
67	      if (collidesAt(world, player.position, PLAYER_HALF_WIDTH, PLAYER_HEIGHT)) {
68	        player.position[axis] -= step;
69	        if (axis === "y" && step < 0) player.onGround = true;
70	        if (axis === "y") player.velocity.y = 0;
71	        break;
72	      }
73	      remaining -= step;
74	    }
75	  };
76	
77	  const forwardInput = (move.forward ? 1 : 0) - (move.back ? 1 : 0);
78	  const strafeInput = (move.right ? 1 : 0) - (move.left ? 1 : 0);
79	  const wantsJump = move.jump;
80	  const crouching = move.crouch;
81	
82	  forwardFromYaw(player.yaw, scratchForward);
83	  scratchRight.crossVectors(scratchForward, UP).normalize();
84	  scratchMoveDir.set(0, 0, 0);
85	  scratchMoveDir.addScaledVector(scratchForward, forwardInput);
86	  scratchMoveDir.addScaledVector(scratchRight, strafeInput);
87	  if (scratchMoveDir.lengthSq() > 0) scratchMoveDir.normalize();
88	
89	  const speedScale = speedScaleFromHunger(state.hunger);
90	  const canSprint = state.hunger > SPRINT_MIN_HUNGER;
91	  const sprinting = canSprint && forwardInput > 0 && move.sprint && !crouching;
92	  const baseSpeed = crouching ? CROUCH_SPEED : sprinting ? SPRINT_SPEED * speedScale : WALK_SPEED * speedScale;
93	  const speed = baseSpeed * speedMultiplier(player);
94	
95	  player.velocity.x = scratchMoveDir.x * speed;
96	  player.velocity.z = scratchMoveDir.z * speed;
97	
98	  const wasGrounded = player.onGround;
99	  let didJump = false;
100	  if (flying) {
101	    // Flight: direct vertical control, no gravity. Space ascends, crouch
102	    // descends, neither (or both) hovers. Collision still applies in Creative;
103	    // Spectator's noclip is handled in stepAxis.
104	    const ascend = (wantsJump ? 1 : 0) - (crouching ? 1 : 0);
105	    player.velocity.y = ascend * FLY_SPEED;
106	  } else {
107	    player.velocity.y -= GRAVITY * dt;
108	    if (wantsJump && player.onGround && !crouching) {
109	      player.velocity.y = JUMP_VELOCITY + jumpBoostBonus(player);
110	      player.onGround = false;
111	      didJump = true;
112	    }
113	  }
114	
115	  const vyBeforeMove = player.velocity.y;
116	  const startX = player.position.x;
117	  const startZ = player.position.z;
118	  const prevX = player.position.x;
119	  const prevZ = player.position.z;
120	
121	  player.onGround = false;
122	  stepAxis("x", player.velocity.x * dt);
123	  stepAxis("z", player.velocity.z * dt);
124	  stepAxis("y", player.velocity.y * dt);
125	
126	  // Depenetration: if still colliding after movement, nudge up (skipped in noclip).
127	  if (!noclip && collidesAt(world, player.position, PLAYER_HALF_WIDTH, PLAYER_HEIGHT)) {
128	    for (let i = 0; i < 5; i += 1) {
129	      player.position.y += 0.2;
130	      if (!collidesAt(world, player.position, PLAYER_HALF_WIDTH, PLAYER_HEIGHT)) break;
131	    }
132	  }
133	
134	  // While flying, crouch means "descend" — don't snap the player back from edges.
135	  if (!flying && crouching && (player.onGround || wasGrounded) && !hasSupportUnderPlayer(world, player.position, PLAYER_HALF_WIDTH + 0.12)) {
136	    player.position.x = prevX;
137	    player.position.z = prevZ;
138	    player.velocity.x = 0;
139	    player.velocity.z = 0;
140	  }
141	
142	  player.position.x = Math.min(world.sizeX - WORLD_BORDER_PADDING, Math.max(WORLD_BORDER_PADDING, player.position.x));
143	  player.position.z = Math.min(world.sizeZ - WORLD_BORDER_PADDING, Math.max(WORLD_BORDER_PADDING, player.position.z));
144	
145	  if (!wasGrounded && player.onGround && vyBeforeMove < -14) {
146	    // Any fall hard enough to trigger this deals at least half a heart; Feather
147	    // Falling on worn boots softens the landing before armor mitigation.
148	    const raw = Math.min(19, Math.floor((-vyBeforeMove - 13) * 0.5));
149	    const softened = raw * (1 - featherFallingReduction(state.equippedArmor.boots));
150	    applyDamage(Math.max(1, Math.round(softened)));
151	  }
152	
153	  const inVoid = player.position.y < -4;
154	  if (inVoid) {
155	    timers.voidTimer += dt;
156	    if (timers.voidTimer >= 0.4) {
157	      applyDamage(1);
158	      timers.voidTimer = 0;
159	    }
160	  } else {
161	    timers.voidTimer = 0;
162	  }
163	
164	  const horizontalDistance = Math.hypot(player.position.x - startX, player.position.z - startZ);
165	  const moving = horizontalDistance > 1e-4;
166	  const didSprint = sprinting && moving;
167	  const didWalk = !didSprint && moving;
168	  const didLand = !wasGrounded && player.onGround && vyBeforeMove < 0;
169	  return { didSprint, didWalk, didJump, didLand, landImpact: didLand ? -vyBeforeMove : 0, horizontalDistance };
170	}

