1	import {
2	  HEALTH_REGEN_INTERVAL_SECONDS,
3	  JUMPS_PER_HUNGER,
4	  EYE_HEIGHT,
5	  LAVA_BURN_SECONDS,
6	  LAVA_DAMAGE_HP,
7	  LAVA_DAMAGE_INTERVAL_SECONDS,
8	  MAX_HUNGER,
9	  MAX_HEARTS,
10	  MAX_OXYGEN,
11	  OXYGEN_DROWN_HP,
12	  OXYGEN_DROWN_INTERVAL_SECONDS,
13	  OXYGEN_HOLD_SECONDS,
14	  OXYGEN_REFILL_SECONDS,
15	  PLAYER_HEIGHT,
16	  REGEN_MIN_HUNGER,
17	  SPRINT_BLOCKS_PER_HUNGER,
18	  STARVATION_HP,
19	  STARVATION_INTERVAL_SECONDS,
20	  WATER_DAMAGE_DELAY_SECONDS,
21	  WATER_DAMAGE_HP,
22	  WATER_DAMAGE_INTERVAL_SECONDS,
23	  WALK_BLOCKS_PER_HUNGER
24	} from "@/lib/game/config";
25	import { BlockId } from "@/lib/world";
26	import { takesDamage } from "@/lib/game/gameModes";
27	import { regenIntervalScale, starves, starvationFloorHp } from "@/lib/game/difficulties";
28	import type { GameState } from "../state";
29	import type { MoveTickResult } from "./playerMotion";
30	
31	/** Movement speed multiplier from the hunger level, with a small full-hunger bonus. */
32	export function speedScaleFromHunger(hunger: number): number {
33	  const ratio = Math.max(0, Math.min(1, hunger / MAX_HUNGER));
34	  return 0.62 + ratio * 0.38 + (ratio >= 0.99 ? 0.08 : 0);
35	}
36	
37	/** Drains hunger from accumulated sprint/walk distance and jumps. Creative/Spectator never hunger. */
38	export function tickHungerDrain(state: GameState, move: MoveTickResult): void {
39	  if (!takesDamage(state.gameMode)) return;
40	  const { timers } = state;
41	  let drain = 0;
42	
43	  if (move.didSprint) {
44	    timers.sprintDistanceBudget += move.horizontalDistance;
45	    while (timers.sprintDistanceBudget >= SPRINT_BLOCKS_PER_HUNGER) {
46	      timers.sprintDistanceBudget -= SPRINT_BLOCKS_PER_HUNGER;
47	      drain += 1;
48	    }
49	  } else if (move.didWalk) {
50	    timers.walkDistanceBudget += move.horizontalDistance;
51	    while (timers.walkDistanceBudget >= WALK_BLOCKS_PER_HUNGER) {
52	      timers.walkDistanceBudget -= WALK_BLOCKS_PER_HUNGER;
53	      drain += 1;
54	    }
55	  }
56	  if (move.didJump) {
57	    timers.jumpBudget += 1;
58	    while (timers.jumpBudget >= JUMPS_PER_HUNGER) {
59	      timers.jumpBudget -= JUMPS_PER_HUNGER;
60	      drain += 1;
61	    }
62	  }
63	
64	  if (drain > 0) state.hunger = Math.max(0, state.hunger - drain);
65	}
66	
67	/**
68	 * Regenerates half a heart every interval while alive, hurt, and fed enough.
69	 * Creative/Spectator stay topped up. Difficulty scales the cadence — Peaceful
70	 * heals twice as fast (regenIntervalScale 0.5) as its build-in-peace mercy.
71	 */
72	export function tickHealthRegen(state: GameState, dt: number): void {
73	  if (!takesDamage(state.gameMode)) {
74	    state.hearts = MAX_HEARTS;
75	    state.timers.regenTimer = 0;
76	    return;
77	  }
78	  if (!state.isDead && state.hearts < MAX_HEARTS && state.hunger >= REGEN_MIN_HUNGER) {
79	    const interval = HEALTH_REGEN_INTERVAL_SECONDS * regenIntervalScale(state.difficulty);
80	    state.timers.regenTimer += dt;
81	    if (state.timers.regenTimer >= interval) {
82	      state.hearts = Math.min(MAX_HEARTS, state.hearts + 1);
83	      state.timers.regenTimer = 0;
84	    }
85	  } else {
86	    state.timers.regenTimer = 0;
87	  }
88	}
89	
90	/**
91	 * Starvation. While hunger sits at 0 the player loses STARVATION_HP every
92	 * interval, down to a difficulty-scaled floor: Easy stops at 10 HP, Normal at
93	 * 1 HP (half a heart), Hard goes all the way to 0 — a kill. Peaceful never
94	 * starves, and Creative/Spectator can't (their hunger is pinned full anyway).
95	 * Mirrors poison's floored chip-damage, but keyed on hunger == 0 rather than a
96	 * timed effect: Easy/Normal route through `applyFloored` (never lethal), Hard
97	 * (floor 0) through `applyLethal`, which can deliver the killing blow.
98	 */
99	export function tickStarvation(
100	  state: GameState,
101	  dt: number,
102	  applyFloored: (amount: number, floorHp: number) => void,
103	  applyLethal: (amount: number) => void
104	): void {
105	  if (!takesDamage(state.gameMode) || !starves(state.difficulty) || state.isDead || state.hunger > 0) {
106	    state.timers.starvationTimer = 0;
107	    return;
108	  }
109	  const floor = starvationFloorHp(state.difficulty);
110	  state.timers.starvationTimer += dt;
111	  while (state.timers.starvationTimer >= STARVATION_INTERVAL_SECONDS && !state.isDead) {
112	    state.timers.starvationTimer -= STARVATION_INTERVAL_SECONDS;
113	    if (floor <= 0) applyLethal(STARVATION_HP);
114	    else applyFloored(STARVATION_HP, floor);
115	  }
116	}
117	
118	/** Damages a continuously immersed player after one minute; leaving water fully resets the clock. */
119	export function tickWaterExposure(state: GameState, dt: number, applyDamage: (amount: number) => void): void {
120	  const { player, timers, world } = state;
121	  const x = Math.floor(player.position.x);
122	  const y = Math.floor(player.position.y + PLAYER_HEIGHT * 0.5);
123	  const z = Math.floor(player.position.z);
124	  if (world.get(x, y, z) !== BlockId.Water) {
125	    timers.waterExposureTimer = 0;
126	    timers.waterDamageTimer = 0;
127	    return;
128	  }
129	
130	  timers.waterExposureTimer += dt;
131	  if (timers.waterExposureTimer <= WATER_DAMAGE_DELAY_SECONDS) return;
132	
133	  timers.waterDamageTimer += dt;
134	  while (timers.waterDamageTimer >= WATER_DAMAGE_INTERVAL_SECONDS && !state.isDead) {
135	    timers.waterDamageTimer -= WATER_DAMAGE_INTERVAL_SECONDS;
136	    applyDamage(WATER_DAMAGE_HP);
137	  }
138	}
139	
140	/**
141	 * Burns the player on lava contact. Unlike water there is no grace period —
142	 * touching lava (standing on it or wading into it) deals armor-bypassing damage
143	 * at once and keeps burning for LAVA_BURN_SECONDS after escaping. Lava is solid,
144	 * so "contact" means the block at the feet, just under them, or at body height.
145	 */
146	export function tickLavaExposure(state: GameState, dt: number, applyDamage: (amount: number) => void, fireImmune = false): void {
147	  const { player, timers, world } = state;
148	  // Fire Resistance fully negates lava burn — no damage, no lingering burn timer.
149	  if (fireImmune) {
150	    timers.lavaBurnTimer = 0;
151	    timers.lavaDamageTimer = 0;
152	    return;
153	  }
154	  const x = Math.floor(player.position.x);
155	  const z = Math.floor(player.position.z);
156	  const py = player.position.y;
157	  const touching =
158	    world.get(x, Math.floor(py - 0.1), z) === BlockId.Lava || // the block underfoot (standing on lava)
159	    world.get(x, Math.floor(py), z) === BlockId.Lava || // the feet cell (wading in)
160	    world.get(x, Math.floor(py + PLAYER_HEIGHT * 0.5), z) === BlockId.Lava; // body height
161	
162	  if (touching) {
163	    // First touch fires a hit immediately (no half-second of free standing).
164	    if (timers.lavaBurnTimer <= 0) timers.lavaDamageTimer = LAVA_DAMAGE_INTERVAL_SECONDS;
165	    timers.lavaBurnTimer = LAVA_BURN_SECONDS;
166	  }
167	
168	  if (timers.lavaBurnTimer <= 0) {
169	    timers.lavaDamageTimer = 0;
170	    return;
171	  }
172	  timers.lavaBurnTimer = Math.max(0, timers.lavaBurnTimer - dt);
173	  timers.lavaDamageTimer += dt;
174	  while (timers.lavaDamageTimer >= LAVA_DAMAGE_INTERVAL_SECONDS && !state.isDead) {
175	    timers.lavaDamageTimer -= LAVA_DAMAGE_INTERVAL_SECONDS;
176	    applyDamage(LAVA_DAMAGE_HP);
177	  }
178	}
179	
180	/**
181	 * Drowning. While the head (eye-height cell) is underwater the breath meter
182	 * drains over OXYGEN_HOLD_SECONDS; once empty, drowning deals armor-bypassing
183	 * damage every interval. Surfacing refills the meter quickly. Keyed on the head,
184	 * so wading chest-deep never drowns you — distinct from the body-keyed 60s
185	 * water-exposure timer, which still runs in parallel.
186	 */
187	export function tickOxygen(state: GameState, dt: number, applyDamage: (amount: number) => void, waterBreathing = false): void {
188	  const { player, timers, world } = state;
189	  // Creative/Spectator never drown — keep the lungs full so the bubble bar hides.
190	  if (!takesDamage(state.gameMode)) {
191	    state.oxygen = MAX_OXYGEN;
192	    timers.drownTimer = 0;
193	    return;
194	  }
195	  // Water Breathing keeps the lungs full and immune to drowning.
196	  if (waterBreathing) {
197	    state.oxygen = MAX_OXYGEN;
198	    timers.drownTimer = 0;
199	    return;
200	  }
201	  const x = Math.floor(player.position.x);
202	  const headY = Math.floor(player.position.y + EYE_HEIGHT);
203	  const z = Math.floor(player.position.z);
