10	/**
11	 * Minimal GameState with just the fields the fishing system reads. A water surface
12	 * sits at (8,7,5); the player at (8.5,6,8.5) looking -Z aims straight at it.
13	 */
14	function makeState(): GameState {
15	  const world = new VoxelWorld(16, 16, 16, 1);
16	  world.set(8, 7, 5, BlockId.Water); // air above by default → a castable surface
17	  const inventory = Array.from({ length: 9 }, () => createEmptySlot());
18	  inventory[0] = createSlot("fishing_rod", 1);
19	  const state = {
20	    world,
21	    inventory,
22	    selectedSlot: 0,
23	    equippedArmor: createEmptyArmorEquipment(),
24	    fishing: null,
25	    isDead: false,
26	    xp: 0,
27	    position: new THREE.Vector3(8.5, 6, 8.5),
28	    velocity: new THREE.Vector3(),
29	    yaw: 0,
30	    pitch: 0,
31	    onGround: true
32	  } as unknown as GameState;
33	  // The flat fixture IS its own player (the old single-player shape): flat
34	  // reads and player-scoped helpers bridged via state.player hit one object.
35	  (state as { player: unknown }).player = state;
36	  return state;
37	}
