59	const NO_ENEMIES: ReadonlySet<MobFaction> = new Set<MobFaction>();
60	
61	/**
62	 * The shared enmity table — which factions each faction will attack. "Fighters"
63	 * (hostile/raider/ally) hunt enemy-faction mobs; wild animals and villagers never
64	 * fight. Hostiles & raiders go after villagers and pets; pets defend against
65	 * hostiles & raiders.
66	 */
67	const ENEMY_FACTIONS: Record<MobFaction, ReadonlySet<MobFaction>> = {
68	  wild: NO_ENEMIES,
69	  villager: NO_ENEMIES,
70	  hostile: new Set<MobFaction>(["villager", "ally"]),
71	  raider: new Set<MobFaction>(["villager", "ally"]),
72	  ally: new Set<MobFaction>(["hostile", "raider"])
73	};
74	
75	/** Factions a villager flees from. */
76	const THREAT_FACTIONS: ReadonlySet<MobFaction> = new Set<MobFaction>(["hostile", "raider"]);
77	
78	/**
79	 * Victim factions whose death credits the player with loot + XP. A pet's kill
80	 * still feeds you ("your wolf hunts for you"); a slain villager or pet yields
81	 * nothing — which also closes the XP leak of farming mobs that kill each other.
82	 */
83	const CREDITED_FACTIONS: ReadonlySet<MobFaction> = new Set<MobFaction>(["wild", "hostile", "raider"]);
84	
85	function horizDistSq(a: MobState, b: MobState): number {
86	  const dx = a.position.x - b.position.x;
87	  const dz = a.position.z - b.position.z;
88	  return dx * dx + dz * dz;
89	}
90	
91	function mobById(state: GameState, id: number): MobState | null {
92	  for (const other of state.mobs) if (other.id === id) return other;
93	  return null;
94	}
95	
96	/**
97	 * The mob (if any) this fighter is hunting. It keeps its cached `targetId` while
98	 * that mob is alive, still an enemy, and in range; otherwise it re-scans for the
99	 * nearest enemy-faction mob — but only every MOB_RETARGET_SECONDS, so the per-mob
100	 * tick stays O(N) and full scans amortize to ~1–2 Hz per fighter. Non-fighters
101	 * (wild/villager) have no enemies and return null immediately.
102	 */
103	function selectMobTarget(state: GameState, mob: MobState): MobState | null {
104	  const enemies = ENEMY_FACTIONS[mob.faction];
105	  if (enemies.size === 0) return null;
106	  const rangeSq = mob.detectRange * mob.detectRange;
107	  if (mob.targetId !== null && mob.retargetTimer > 0) {
108	    const cached = mobById(state, mob.targetId);
109	    if (cached && cached.hp > 0 && enemies.has(cached.faction) && horizDistSq(mob, cached) < rangeSq) return cached;
110	  }
111	  mob.retargetTimer = MOB_RETARGET_SECONDS;
112	  let best: MobState | null = null;
113	  let bestSq = rangeSq;
114	  for (const other of state.mobs) {
115	    if (other === mob || other.hp <= 0 || !enemies.has(other.faction)) continue;
116	    const d = horizDistSq(mob, other);
117	    if (d < bestSq) {
118	      bestSq = d;
119	      best = other;
120	    }
121	  }
122	  mob.targetId = best ? best.id : null;
123	  return best;
124	}
125	
126	/** Nearest hostile/raider within `range` of a villager (drives its flee), or null. */
127	function nearestThreat(state: GameState, mob: MobState, range: number): MobState | null {
128	  let best: MobState | null = null;
129	  let bestSq = range * range;
130	  for (const other of state.mobs) {
131	    if (other.hp <= 0 || !THREAT_FACTIONS.has(other.faction)) continue;
132	    const d = horizDistSq(mob, other);
133	    if (d < bestSq) {
134	      bestSq = d;
135	      best = other;
136	    }
137	  }
138	  return best;
139	}
140	
141	/** True when nothing solid blocks the segment from a fighter's eye to its target — so it can't bite through a wall/door. */
142	function mobVsMobLineOfSight(world: GameState["world"], mob: MobState, dx: number, dy: number, dz: number): boolean {
143	  scratchRay.set(dx, dy, dz);
144	  if (scratchRay.lengthSq() <= 1e-6) return true;
145	  const dist = scratchRay.length();
146	  scratchMobEye.set(mob.position.x, mob.position.y + mob.halfHeight * 0.35, mob.position.z);
147	  return voxelRaycast(world, scratchMobEye, scratchRay.normalize(), dist) === null;
148	}
149	
150	/**
151	 * A ranged mob looses an arrow from its eye toward the player's chest, leading a
152	 * moving target by a fraction of the arrow's travel time. The arrow is not
153	 * player-owned, so it only ever hits the player (never the firer or other mobs).
154	 */
155	function fireMobArrow(state: GameState, player: PlayerState, mob: MobState, damage: number, speed: number, emit: EmitGameEvent): void {
156	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
157	  const dist = Math.hypot(player.position.x - mob.position.x, player.position.z - mob.position.z);
158	  const lead = (dist / speed) * SKELETON_LEAD_FACTOR;
159	  scratchAim.set(
160	    player.position.x + player.velocity.x * lead - mob.position.x,
161	    player.position.y + 0.9 - eyeY,
162	    player.position.z + player.velocity.z * lead - mob.position.z
163	  );
164	  spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
165	    speed,
166	    damage,
167	    knockback: MOB_ARROW_KNOCKBACK,
168	    fromPlayer: false,
169	    ttl: ARROW_TTL
170	  });
