8	 * the creeper branch in mobAI can pass its `deps` straight through.
9	 */
10	export type ExplosionDeps = {
11	  /** Armor-mitigated combat damage to a specific player — a blast hits everyone in range. */
12	  damagePlayer: (player: PlayerState, amount: number) => void;
13	  rng: () => number;
14	  emit: EmitGameEvent;
15	};
16	
17	/** Blocks the blast can never break (mirrors the mining unbreakables + worldgen hazards). */
18	function isBlastproof(block: BlockId): boolean {
19	  return block === BlockId.Bedrock || block === BlockId.Spawner || block === BlockId.Lava;
20	}
21	
22	/** Higher = harder to destroy: the blast strength at a cell must exceed this to break it. */
23	function blastResistance(block: BlockId): number {
24	  switch (block) {
25	    case BlockId.Stone:
26	    case BlockId.Cobblestone:
27	    case BlockId.Brick:
28	    case BlockId.MossyCobblestone:
29	    case BlockId.Furnace:
30	    case BlockId.CoalOre:
31	    case BlockId.SliverOre:
32	    case BlockId.RubyOre:
33	    case BlockId.GoldOre:
34	    case BlockId.SapphireOre:
35	    case BlockId.DiamondOre:
36	      return 2.5;
37	    case BlockId.Chest:
38	      return 1.2;
39	    default:
40	      return 0.4; // dirt, sand, wood, planks, leaves, glass, doors, crops, torches, ...
41	  }
42	}
43	
44	const scratchKnock = new THREE.Vector3();
45	
46	/**
47	 * An explosion centered at (cx,cy,cz). It destroys blocks within `power` (a
48	 * distance falloff weighed against each block's blast resistance), then damages
49	 * the player and mobs out to twice that radius with the same falloff, and emits
50	 * one `explosion` event for the renderer/audio.
51	 *
52	 * It rides the existing single-block edit chokepoint: each destroyed cell goes
53	 * through `blockChanges.set` (which relights locally and records the save delta),
54	 * and `worldMeshDirty` is set **once** so the whole crater costs a single remesh.
55	 * It never removes mobs — it only lowers hp — so it is safe to call from inside
56	 * the mob tick loop; the caller sweeps any mob that reaches 0 hp.
57	 */
58	export function explode(state: GameState, cx: number, cy: number, cz: number, power: number, deps: ExplosionDeps): void {
59	  const { world } = state;
60	  const radius = Math.ceil(power);
61	  const bx = Math.floor(cx);
62	  const by = Math.floor(cy);
63	  const bz = Math.floor(cz);
64	  let changed = false;
65	
66	  for (let dx = -radius; dx <= radius; dx += 1) {
67	    for (let dy = -radius; dy <= radius; dy += 1) {
68	      for (let dz = -radius; dz <= radius; dz += 1) {
69	        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
70	        if (dist > power) continue;
71	        const x = bx + dx;
72	        const y = by + dy;
73	        const z = bz + dz;
74	        if (!world.inBounds(x, y, z) || y <= 1) continue;
75	        const block = world.get(x, y, z) as BlockId;
76	        if (block === BlockId.Air || isBlastproof(block)) continue;
77	        if (power * (1 - dist / power) <= blastResistance(block)) continue;
78	
79	        if (block === BlockId.Tnt) {
80	          // Chain reaction: light neighboring TNT on a short randomized fuse
81	          // instead of vaporizing it, so blasts ripple.
82	          const idx = world.index(x, y, z);
83	          if (!state.primedTnt.has(idx)) {
84	            state.primedTnt.set(idx, TNT_CHAIN_FUSE_MIN_SECONDS + deps.rng() * (TNT_CHAIN_FUSE_MAX_SECONDS - TNT_CHAIN_FUSE_MIN_SECONDS));
85	            deps.emit({ type: "tntPrimed", x, y, z });
86	          }
87	          continue;
88	        }
89	        if (isDoorBlock(block)) {
90	          const door = doorState(block)!;
91	          const otherY = door.upper ? y - 1 : y + 1;
92	          state.blockChanges.set(x, y, z, BlockId.Air);
93	          if (isDoorBlock(world.get(x, otherY, z) as BlockId)) state.blockChanges.set(x, otherY, z, BlockId.Air);
94	        } else {
95	          state.blockChanges.set(x, y, z, BlockId.Air);
96	        }
97	        changed = true;
98	      }
99	    }
100	  }
101	  if (changed) state.worldMeshDirty = true;
102	
103	  const damageRange = power * 2;
104	  const peak = power * EXPLOSION_DAMAGE_PER_POWER;
105	
106	  // Players: armor-aware damage + knockback away from the blast — a blast is
107	  // indiscriminate and hits every player in range, not just whoever is primary.
108	  for (const player of state.players.values()) {
109	    const pdist = Math.hypot(player.position.x - cx, player.position.y - cy, player.position.z - cz);
110	    if (pdist >= damageRange) continue;
111	    const falloff = 1 - pdist / damageRange;
112	    deps.damagePlayer(player, Math.max(1, Math.round(peak * falloff)));
113	    if (pdist > 0.001) {
114	      scratchKnock
115	        .set(player.position.x - cx, player.position.y - cy, player.position.z - cz)
116	        .normalize()
117	        .multiplyScalar(power * falloff);
118	      player.velocity.x += scratchKnock.x;
119	      player.velocity.z += scratchKnock.z;
120	      player.velocity.y = Math.max(player.velocity.y, Math.abs(scratchKnock.y) + 2);
121	    }
122	  }
123	
124	  // Mobs: damage only — the caller removes any that reach 0 hp (so this is safe
125	  // to run mid mob-loop). A light directional shove reads as the blast pushing them.
126	  for (const mob of state.mobs) {
127	    const mdist = Math.hypot(mob.position.x - cx, mob.position.y - cy, mob.position.z - cz);
128	    if (mdist >= damageRange) continue;
129	    mob.hp -= Math.max(1, Math.round(peak * (1 - mdist / damageRange)));
130	    if (mdist > 0.001) mob.direction.set(mob.position.x - cx, 0, mob.position.z - cz).normalize();
131	  }
132	
133	  deps.emit({ type: "explosion", x: cx, y: cy, z: cz, power });
134	}
135	
136	/** Lights the TNT block at (x,y,z) on a full fuse (no-op if already lit). */
137	export function primeTnt(state: GameState, x: number, y: number, z: number, emit: EmitGameEvent): void {
138	  const idx = state.world.index(x, y, z);
139	  if (state.primedTnt.has(idx)) return;
140	  state.primedTnt.set(idx, TNT_FUSE_SECONDS);
141	  emit({ type: "tntPrimed", x, y, z });
142	}
143	
144	/**
145	 * Counts down lit TNT and detonates it. A TNT block mined or replaced before its
146	 * fuse runs out is silently dropped (the block check). Detonations run after the
147	 * countdown pass so a blast's chain-priming can't mutate the map mid-iteration.
148	 */
149	export function tickPrimedTnt(state: GameState, dt: number, deps: ExplosionDeps): void {
150	  if (state.primedTnt.size === 0) return;
151	  const { world } = state;
152	  const layer = world.sizeX * world.sizeZ;
153	  const detonations: Array<[number, number, number]> = [];
154	
155	  for (const [idx, timer] of state.primedTnt) {
156	    const y = Math.floor(idx / layer);
157	    const rem = idx - y * layer;
158	    const z = Math.floor(rem / world.sizeX);
159	    const x = rem - z * world.sizeX;
160	    if (world.get(x, y, z) !== BlockId.Tnt) {
161	      state.primedTnt.delete(idx); // mined or overwritten → forget it
162	      continue;
163	    }
164	    const next = timer - dt;
165	    if (next > 0) {
166	      state.primedTnt.set(idx, next);
167	    } else {
168	      state.primedTnt.delete(idx);
169	      detonations.push([x, y, z]);
170	    }
171	  }
172	
173	  for (const [x, y, z] of detonations) {
174	    state.blockChanges.set(x, y, z, BlockId.Air);
175	    state.worldMeshDirty = true;
176	    explode(state, x + 0.5, y + 0.5, z + 0.5, TNT_EXPLOSION_POWER, deps);
177	  }
178	}

