85	 * column at least 2 deep; a dry world (Superflat) or an inland center simply
86	 * yields fewer or zero fish — the sampler fails closed, never onto land.
87	 * pushMob expects ground-level feet, so the swim point converts to feet-y.
88	 */
89	export function spawnAquaticGroup(state: GameState, kind: MobKind, count: number, centerX: number, centerZ: number, radius: number, rng: () => number): void {
90	  for (let i = 0; i < count; i += 1) {
91	    const pos = randomWaterPointNear(state.world, centerX, centerZ, radius, rng);
92	    if (!pos) return;
93	    pushMob(state, kind, false, pos.x, pos.y - mobHalfHeight(kind), pos.z, rng);
94	  }
95	}
96	
97	/**
98	 * The day-one population around the player's spawn point. Passives scatter
99	 * over a wider ring than hostiles so the spawn area doesn't feel like a
100	 * petting zoo; hostiles stay closer (the dawn-aggro behavior tests document).
101	 */
102	export function spawnInitialMobs(state: GameState, rng: () => number, surfaceYAt: SurfaceYAtFn): void {
103	  const centerX = state.player.position.x;
104	  const centerZ = state.player.position.z;
105	  const passiveRadius = RENDER_RADIUS * 1.2;
106	  const hostileRadius = RENDER_RADIUS * 0.7;
107	  const groups: Array<[MobKind, boolean, number, number]> = [
108	    ["sheep", false, 6, passiveRadius],
109	    ["chicken", false, 5, passiveRadius],
110	    ["horse", false, 3, passiveRadius],
111	    ["cow", false, 4, passiveRadius],
112	    ["pig", false, 4, passiveRadius],
113	    // Wild wolves and cats roam with the other animals (passive, flee the player)
114	    // until tamed with a bone / raw fish — without these they'd never appear and
115	    // companions would be unreachable.
116	    ["wolf", false, 4, passiveRadius],
117	    ["cat", false, 3, passiveRadius],
118	    // Villagers no longer scatter loosely — they live in generated villages now
119	    // (see spawnVillageResidents), so the world's villager population is its
120	    // settlements. A village-less world (e.g. all-ocean) simply has no villagers.
121	    ["zombie", true, 8, hostileRadius],
122	    ["skeleton", true, 6, hostileRadius],
123	    ["spider", true, 6, hostileRadius],
124	    ["creeper", true, 4, hostileRadius]
125	  ];
126	  // Peaceful spawns no hostiles at all — only the passive groups populate the world.
127	  const spawnHostiles = hostilesSpawn(state.difficulty);
128	  for (const [kind, hostile, count, radius] of groups) {
129	    if (hostile && !spawnHostiles) continue;
130	    // Hostiles keep a minimum standoff so nothing (notably a creeper) starts the
131	    // game point-blank; passives may roam right up to the spawn area.
132	    spawnMobGroup(state, { kind, hostile, count, centerX, centerZ, radius, minRadius: hostile ? HOSTILE_SPAWN_MIN_RADIUS : 0 }, rng, surfaceYAt);
133	  }
134	  // Fish school in whatever water lies near spawn; a landlocked spawn gets none
135	  // (the aquatic director repopulates oceans the player sails to later).
136	  spawnAquaticGroup(state, "cod", 6, centerX, centerZ, passiveRadius, rng);
137	  spawnAquaticGroup(state, "salmon", 4, centerX, centerZ, passiveRadius, rng);
138	}
139	
140	/**
141	 * Trickles fish in around the player so any ocean feels stocked, not just the
142	 * spawn-time one. Every interval it tops the population up toward AQUATIC_CAP,
143	 * one small school at a time; without nearby deep water the sampler fails
144	 * closed and the tick is a no-op (Superflat never spawns a fish).
145	 */
146	export function tickAquaticSpawnDirector(state: GameState, dt: number, rng: () => number): void {
147	  state.timers.aquaticSpawnTimer += dt;
148	  if (state.timers.aquaticSpawnTimer < AQUATIC_SPAWN_INTERVAL_SECONDS) return;
149	  state.timers.aquaticSpawnTimer = 0;
150	
151	  let aquatic = 0;
152	  for (const mob of state.mobs) if (MOB_TEMPLATES[mob.kind].aquatic) aquatic += 1;
153	  if (aquatic >= AQUATIC_CAP) return;
154	
155	  const kind: MobKind = rng() < 0.6 ? "cod" : "salmon";
156	  const count = Math.min(AQUATIC_CAP - aquatic, 1 + (rng() > 0.6 ? 1 : 0));
157	  spawnAquaticGroup(state, kind, count, state.player.position.x, state.player.position.z, RENDER_RADIUS * 0.85, rng);
158	}
159	
160	/**
161	 * Seeds each village center with its resident villager population (faction
162	 * "villager", so they persist with the world). Called once when a world has no
163	 * villagers yet — a fresh world or one upgraded from a pre-village save; a reload
164	 * of a populated world restores its residents instead, so they aren't doubled.
165	 */
166	export function spawnVillageResidents(state: GameState, sites: Array<{ x: number; z: number }>, rng: () => number, surfaceYAt: SurfaceYAtFn): void {
167	  for (const site of sites) {
168	    for (let i = 0; i < GEN.villagersPerVillage; i += 1) {
169	      const pos = randomLandPointNear(state.world, surfaceYAt, site.x, site.z, 8, rng, 0);
170	      pushMob(state, "villager", false, pos.x, pos.y, pos.z, rng);
171	    }
172	  }
173	}
174	
175	/**
176	 * Assigns a trade profession (round-robin) to every villager that doesn't have
177	 * one yet — newly seeded residents on a fresh world. Restored residents keep
178	 * their saved profession, so this skips them (they're not professionless).
179	 */
180	export function assignVillagerProfessions(state: GameState): void {
181	  let next = 0;
182	  for (const mob of state.mobs) {
183	    if (mob.faction !== "villager" || mob.profession != null) continue;
184	    mob.profession = PROFESSIONS[next % PROFESSIONS.length];
185	    next += 1;
186	  }
187	}
188	
189	/** Trickles hostile mobs in around the player at night, up to the cap. Difficulty scales the cadence and cap; Peaceful spawns none. */
190	export function tickHostileSpawnDirector(state: GameState, dt: number, rng: () => number, surfaceYAt: SurfaceYAtFn): void {
191	  if (!hostilesSpawn(state.difficulty)) return;
192	  state.timers.hostileSpawnTimer += dt;
193	  const interval = HOSTILE_SPAWN_INTERVAL_SECONDS * hostileSpawnIntervalScale(state.difficulty);
194	  if (state.daylight >= HOSTILE_SPAWN_BELOW_DAYLIGHT || state.timers.hostileSpawnTimer < interval) return;
195	  state.timers.hostileSpawnTimer = 0;
196	
197	  const cap = Math.round(HOSTILE_CAP * hostileCapScale(state.difficulty));
198	  const livingHostiles = state.mobs.filter((mob) => mob.hostile).length;
199	  if (livingHostiles >= cap) return;
200	
201	  const spawnKinds: Array<"zombie" | "skeleton" | "spider" | "creeper"> = ["zombie", "skeleton", "spider", "creeper"];
202	  const kind = spawnKinds[Math.floor(rng() * spawnKinds.length)];
203	  // A wave is 1–2 mobs, but never more than the slots left under the cap — so a
204	  // 2-pack rolled at cap-1 can't overshoot (especially Easy's tighter cap of 8).
205	  spawnMobGroup(
206	    state,
207	    {
208	      kind,
209	      hostile: true,
210	      count: Math.min(cap - livingHostiles, 1 + (rng() > 0.7 ? 1 : 0)),
211	      centerX: state.player.position.x,
212	      centerZ: state.player.position.z,
213	      radius: Math.max(26, RENDER_RADIUS * 0.85),
214	      minRadius: HOSTILE_SPAWN_MIN_RADIUS
215	    },
216	    rng,
217	    surfaceYAt
218	  );
219	}
220	
221	const SPAWNER_KINDS: ReadonlyArray<"zombie" | "skeleton" | "spider"> = ["zombie", "skeleton", "spider"];
222	
223	/**
224	 * Drips hostiles from dungeon spawners. On each interval, every intact spawner
225	 * with the player inside its activation radius spawns one hostile on the room
226	 * floor (feet at the spawner's own y, not the surface), bounded by a local
227	 * cluster cap and the shared global HOSTILE_CAP. Time-independent — dungeons
228	 * are dark. Spawner positions come from the session-derived index set, so
229	 * mining out a spawner block stops it (the world.get check below).

