24	const scratchEye = new THREE.Vector3();
25	const scratchDir = new THREE.Vector3();
26	const scratchForward = new THREE.Vector3();
27	const scratchRight = new THREE.Vector3();
28	const scratchCandidate = new THREE.Vector3();
29	
30	type VehicleSpec = {
31	  speed: number;
32	  halfWidth: number;
33	  halfLength: number;
34	};
35	
36	const VEHICLE_SPECS: Record<VehicleKind, VehicleSpec> = {
37	  raft: { speed: RAFT_SPEED, halfWidth: RAFT_HALF_WIDTH, halfLength: RAFT_HALF_LENGTH },
38	  ship: { speed: SHIP_SPEED, halfWidth: SHIP_HALF_WIDTH, halfLength: SHIP_HALF_LENGTH }
39	};
40	
41	function specFor(kind: VehicleKind): VehicleSpec {
42	  return VEHICLE_SPECS[kind];
43	}
44	
45	function makeVehicle(state: GameState, kind: VehicleKind, x: number, y: number, z: number, yaw: number): VehicleState {
46	  return {
47	    id: state.nextVehicleId++,
48	    kind,
49	    position: new THREE.Vector3(x, y, z),
50	    yaw,
51	    rider: null
52	  };
53	}
54	
55	export function restoreVehicle(state: GameState, kind: VehicleKind, x: number, y: number, z: number, yaw: number): void {
56	  // Restore unconditionally — the pose was already field-validated in restoreVehicles.
57	  // We deliberately do NOT re-check water support or overlap here: the world under a
58	  // parked boat may have changed since it was saved (the player dug the water, built a
59	  // pier, etc.), and silently deleting a persisted, crafted entity is worse than keeping
60	  // a stuck one. Movement stays gated by canOccupy, so a beached boat still can't drive
61	  // onto land — it simply sits until the player frees it.
62	  state.vehicles.push(makeVehicle(state, kind, x, y, z, yaw));
63	}
64	
65	// The four rotated footprint corners plus the center, reused across frames. The lone
66	// consumer (vehicleHasWaterSupport) reads it fully before returning and nothing else
67	// calls vehicleCorners concurrently, so a shared, allocation-free buffer is safe — in
68	// line with the scratch* vectors above and the engine's no-alloc-per-tick convention.
69	const scratchCorners: Array<[number, number]> = [
70	  [0, 0],
71	  [0, 0],
72	  [0, 0],
73	  [0, 0],
74	  [0, 0]
75	];
76	
77	function vehicleCorners(vehicle: VehicleState): Array<[number, number]> {
78	  const spec = specFor(vehicle.kind);
79	  const sin = Math.sin(vehicle.yaw);
80	  const cos = Math.cos(vehicle.yaw);
81	  const { x, z } = vehicle.position;
82	  const hw = spec.halfWidth;
83	  const hl = spec.halfLength;
84	  scratchCorners[0][0] = x - hw * cos + hl * sin;
85	  scratchCorners[0][1] = z - hw * sin - hl * cos;
86	  scratchCorners[1][0] = x - hw * cos - hl * sin;
87	  scratchCorners[1][1] = z - hw * sin + hl * cos;
88	  scratchCorners[2][0] = x + hw * cos + hl * sin;
89	  scratchCorners[2][1] = z + hw * sin - hl * cos;
90	  scratchCorners[3][0] = x + hw * cos - hl * sin;
91	  scratchCorners[3][1] = z + hw * sin + hl * cos;
92	  scratchCorners[4][0] = x;
93	  scratchCorners[4][1] = z;
94	  return scratchCorners;
95	}
96	
97	function vehicleHasWaterSupport(state: GameState, vehicle: VehicleState): boolean {
98	  const waterY = Math.floor(vehicle.position.y - 0.2);
99	  const deckY = Math.floor(vehicle.position.y);
100	  for (const [x, z] of vehicleCorners(vehicle)) {
101	    const fx = Math.floor(x);
102	    const fz = Math.floor(z);
103	    if (state.world.get(fx, waterY, fz) !== BlockId.Water) return false;
104	    if (state.world.get(fx, deckY, fz) !== BlockId.Air) return false;
105	  }
106	  return true;
107	}
108	
109	function vehicleOverlaps(a: VehicleState, b: VehicleState): boolean {
110	  const as = specFor(a.kind);
111	  const bs = specFor(b.kind);
112	  const radiusA = Math.hypot(as.halfWidth, as.halfLength);
113	  const radiusB = Math.hypot(bs.halfWidth, bs.halfLength);
114	  return Math.hypot(a.position.x - b.position.x, a.position.z - b.position.z) < radiusA + radiusB;
115	}
116	
117	function vehicleOverlapsAny(state: GameState, vehicle: VehicleState): boolean {
118	  return state.vehicles.some((other) => other.id !== vehicle.id && vehicleOverlaps(vehicle, other));
119	}
120	
121	function canOccupy(state: GameState, vehicle: VehicleState): boolean {
122	  const spec = specFor(vehicle.kind);
123	  const radius = Math.hypot(spec.halfWidth, spec.halfLength);
124	  if (
125	    vehicle.position.x - radius < WORLD_BORDER_PADDING ||
126	    vehicle.position.z - radius < WORLD_BORDER_PADDING ||
127	    vehicle.position.x + radius > state.world.sizeX - WORLD_BORDER_PADDING ||
128	    vehicle.position.z + radius > state.world.sizeZ - WORLD_BORDER_PADDING
129	  ) {
130	    return false;
131	  }
132	  return vehicleHasWaterSupport(state, vehicle) && !vehicleOverlapsAny(state, vehicle);
133	}
134	
135	function mountVehicle(state: GameState, vehicle: VehicleState): void {
136	  if (player.mountedVehicleId !== null) {
137	    const current = state.vehicles.find((v) => v.id === player.mountedVehicleId);
138	    if (current) current.rider = null;
139	  }
140	  vehicle.rider = "player";
141	  player.mountedVehicleId = vehicle.id;
142	  syncPlayerToVehicle(state, vehicle);
143	}
144	
145	function dismountVehicle(state: GameState, vehicle: VehicleState): boolean {
146	  const spec = specFor(vehicle.kind);
147	  const offsets = [
148	    [0, spec.halfLength + 0.8],
149	    [0, -spec.halfLength - 0.8],
150	    [spec.halfWidth + 0.8, 0],
151	    [-spec.halfWidth - 0.8, 0],
152	    [VEHICLE_DISMOUNT_RADIUS, VEHICLE_DISMOUNT_RADIUS],
153	    [-VEHICLE_DISMOUNT_RADIUS, VEHICLE_DISMOUNT_RADIUS],
154	    [VEHICLE_DISMOUNT_RADIUS, -VEHICLE_DISMOUNT_RADIUS],
155	    [-VEHICLE_DISMOUNT_RADIUS, -VEHICLE_DISMOUNT_RADIUS]
156	  ];
157	  const sin = Math.sin(vehicle.yaw);
