218	/**
219	 * Migrates a v15 save to v16 — a pure version bump. `vehicles` is optional, so
220	 * older saves load with no placed rafts/ships.
221	 */
222	export function migrateSaveV15toV16(save: SaveDataV15): SaveData {
223	  return { ...save, version: 16 };
224	}
225	
226	// Storage is injectable so save logic can be tested without a browser.
227	export function readSave(saveKey: string, storage: Storage = localStorage): SaveData | null {
228	  try {
