999	  private removeMobAt = (index: number, lootingLevel = 0, credit = true): void => {
1000	    const state = this.state;
1001	    const mob = state.mobs[index];
1002	    state.mobs.splice(index, 1);
1003	    // Babies drop nothing — only grown animals yield loot. `lootingLevel` is the
1004	    // *killing* melee weapon's Looting (forwarded by tryAttackMob); indirect kills
1005	    // (arrows, thrown spears, explosions) pass 0, since Looting is a melee enchant.
1006	    const drops = credit && mob.ageTimer <= 0 ? rollMobDrops(mob.kind, this.rng, lootingLevel) : [];
1007	    for (const drop of drops) {
1008	      state.inventory = inv.adjustSlotCount(state.inventory, drop.itemId, drop.count) ?? state.inventory;
1009	    }
1010	    // XP on kill, baby-gated like drops; the boss pays a jackpot.
1011	    if (credit && mob.ageTimer <= 0) awardXp(state.player, xpForMob(mob.kind), this.emit);
1012	    this.emit({ type: "mobDied", kind: mob.kind, x: mob.position.x, y: mob.position.y, z: mob.position.z });
1013	    // Drops land straight in inventory (no ground item), so announce them.
1014	    if (drops.length > 0) this.emit({ type: "pickedUp", items: drops });
1015	    // Defeating the boss is the win condition — fire the one-shot victory.
1016	    if (mob.kind === "boss") {
1017	      state.victory = true;
1018	      this.emit({ type: "bossDefeated", x: mob.position.x, y: mob.position.y, z: mob.position.z });
1019	    }
1020	  };
