1024	   * player, consuming the totem. Refuses (keeping the totem) when a boss already
1025	   * walks. Returns true when the click was consumed.
1026	   */
1027	  private trySummonBoss(): boolean {
1028	    const state = this.state;
1029	    const slot = state.inventory[state.selectedSlot];
1030	    if (slot?.id !== "boss_summoner" || slot.count <= 0) return false;
1031	    if (state.mobs.some((mob) => mob.kind === "boss")) {
1032	      this.emit({ type: "summonFailed" });
1033	      return true;
1034	    }
1035	    const point = randomLandPointNear(state.world, this.surfaceYAt, state.player.position.x, state.player.position.z, BOSS_SUMMON_RADIUS, this.rng);
1036	    spawnBoss(state, point.x, point.y, point.z, this.rng);
1037	    state.inventory = inv.adjustSlotCount(state.inventory, "boss_summoner", -1, state.selectedSlot) ?? state.inventory;
1038	    this.emit({ type: "bossSummoned", x: point.x, y: point.y, z: point.z });
1039	    return true;
1040	  }
1041	
1042	  /**
1043	   * Sounds a held Ominous Horn at the nearest village (within RAID_TRIGGER_DISTANCE)
1044	   * to start a raid, consuming the horn. Refuses (keeping it) when a raid is already
1045	   * running; does nothing (returns false, so placement falls through) when no village
1046	   * is in range or the difficulty is Peaceful.
1047	   */
1048	  private tryStartRaid(): boolean {
1049	    const state = this.state;
1050	    const slot = state.inventory[state.selectedSlot];
1051	    if (slot?.id !== "ominous_horn" || slot.count <= 0) return false;
1052	    if (state.raid) {
1053	      this.emit({ type: "raidFailed" });
1054	      return true;
1055	    }
1056	    const { x, z } = state.player.position;
1057	    let nearest: { x: number; z: number } | null = null;
1058	    let bestSq = RAID_TRIGGER_DISTANCE * RAID_TRIGGER_DISTANCE;
1059	    for (const site of state.villageSites) {
1060	      const d = (site.x - x) * (site.x - x) + (site.z - z) * (site.z - z);
1061	      if (d < bestSq) {
1062	        bestSq = d;
1063	        nearest = site;
1064	      }
1065	    }
1066	    if (!nearest || !startRaid(state, nearest.x, nearest.z)) return false;
1067	    state.inventory = inv.adjustSlotCount(state.inventory, "ominous_horn", -1, state.selectedSlot) ?? state.inventory;
1068	    this.emit({ type: "raidStarted", totalWaves: RAID_WAVE_COUNT });
