1100	    t.waterDamageTimer = 0;
1101	    t.drownTimer = 0;
1102	    state.hearts = MAX_HEARTS;
1103	    state.hunger = MAX_HUNGER;
1104	    state.oxygen = MAX_OXYGEN;
1105	
