1109	    state.craftingStation = null;
1110	    state.openContainerIndex = null;
1111	
1112	    if (!isNoclip(next) && (collidesAt(state.world, state.player.position, PLAYER_HALF_WIDTH, PLAYER_HEIGHT) || state.player.position.y < 2)) {
1113	      this.forceUnstuck();
1114	    }
1115	  }
