1118	   * Switches the live difficulty (from the pause menu). The spawn directors and
1119	   * mob AI read state.difficulty every tick, so raising/lowering just changes the
1120	   * numbers they use next tick — the one thing needing action here is dropping to
1121	   * Peaceful, which must clear the hostiles already on the field (the directors
1122	   * only govern *new* spawns). Resetting the starvation accumulator stops a stale
1123	   * timer from biting right after a Peaceful→Hard flip. Unlike switchGameMode this
1124	   * has no respawn-coupled state to guard, so it is allowed even while dead — a
1125	   * player should be able to flip to Peaceful to stop a hostile pile-on.
1126	   */
1127	  private switchDifficulty(next: Difficulty): void {
1128	    const state = this.state;
1129	    if (state.hardcore) return; // locked to Hard for the world's life
1130	    if (!isDifficulty(next) || next === state.difficulty) return;
1131	    state.difficulty = next;
1132	    state.timers.starvationTimer = 0;
