test("a membership the new account already holds isn't duplicated by the merge", async () => {
  // An established account already member of a world…
  await auth.api.signUpEmail({
    body: { email: "veteran@example.com", password: "hunter2hunter2", name: "Veteran" }
  });
  const veteran = (await db.select().from(schema.user).where(eq(schema.user.email, "veteran@example.com")))[0];

  await db.insert(schema.worlds).values({
    id: "world-2",
    ownerId: veteran.id,
    kind: "mp",
    name: "Shared",
    seed: 7,
    worldgenVersion: 11
  });
  await db.insert(schema.worldMembers).values({ worldId: "world-2", userId: veteran.id, role: "owner" });

  // …a guest ALSO joins that world…
  const cookie = await guestCookie();
  const guestId = (await auth.api.getSession({ headers: new Headers({ cookie }) }))!.user.id;
  await db.insert(schema.worldMembers).values({ worldId: "world-2", userId: guestId, role: "member" });

  // …and upgrades into a brand-new account that then ALSO joins? No — the
  // collision case: the guest upgrades to a THIRD account which already has
  // a membership. Simulate by pre-inserting the future membership conflict:
  await auth.api.signUpEmail({
    body: { email: "third@example.com", password: "hunter2hunter2", name: "Third" },
    headers: new Headers({ cookie })
  });
  const third = (await db.select().from(schema.user).where(eq(schema.user.email, "third@example.com")))[0];

  const rows = await db.select().from(schema.worldMembers).where(eq(schema.worldMembers.worldId, "world-2"));
  // Exactly two memberships: the veteran owner and the upgraded account.
  expect(rows).toHaveLength(2);
  expect(rows.filter((r) => r.userId === third.id)).toHaveLength(1);
});

