beforeAll(async () => {
  await GlobalRegistrator.unregister();
  proc = Bun.spawn(["bun", "server/index.ts"], {
    cwd: import.meta.dir + "/..",
    env: { ...process.env, PORT: String(PORT), GAME_TICKET_SECRET: SECRET, PERSISTENCE: "memory" },
    stdout: "pipe",
    stderr: "pipe"
  });
