108	  // The owning shell keys this hook by world id, so the world is fixed for the
109	  // mount's life; capturing it once in refs lets the long-lived rAF/autosave
110	  // effect read the save key and seed without re-subscribing.
111	  const saveKeyRef = useRef(worldSaveKey(opts.world.id));
112	  const worldSeedRef = useRef(opts.world.seed);
113	  const worldTypeRef = useRef(opts.world.worldType);
114	  const worldModeRef = useRef(opts.world.gameMode);
115	  const worldDifficultyRef = useRef(opts.world.difficulty);
116	  const worldHardcoreRef = useRef(opts.world.hardcore);
117	  const [ctx, setCtx] = useState<GameContext | null>(null);
118	  const [locked, setLocked] = useState(false);
119	  const [saveMessage, setSaveMessage] = useState("");
