121	  const [audioSettings, setAudioSettings] = useState<AudioSettings>(DEFAULT_AUDIO_SETTINGS);
122	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
123	  const minimapNodeRef = useRef<HTMLDivElement | null>(null);
124	  const audioRef = useRef<AudioDirector | null>(null);
125	  // The rAF effect must not re-run on volume tweaks — it reads through a ref.
