import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

/**
 * The Postgres connection, lazily created so importing this module never
 * requires DATABASE_URL (the client bundle types against the schema; only
 * route handlers and the game server actually connect). postgres-js runs on
 * both Node (Vercel functions) and Bun (the Fly game server); tests use the
 * PGlite driver via db/testDb.ts instead.
 *
 * `DATABASE_URL=pglite://memory` runs an EPHEMERAL in-process Postgres with
 * the schema pre-applied — the Playwright multiplayer suite and daemon-free
 * local dev use it; data lives exactly as long as the server process.
 */

export type Db = ReturnType<typeof drizzle<typeof schema>>;

let instance: Db | null = null;

export function db(): Db {
  if (instance) return instance;
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set — see .env.example");
  if (url.startsWith("pglite:")) {
    // Lazy requires keep PGlite (a WASM bundle) out of production paths.
    /* eslint-disable @typescript-eslint/no-require-imports */
    const { PGlite } = require("@electric-sql/pglite") as typeof import("@electric-sql/pglite");
    const { drizzle: drizzlePglite } = require("drizzle-orm/pglite") as typeof import("drizzle-orm/pglite");
    const { SCHEMA_DDL } = require("./ddl") as typeof import("./ddl");
    /* eslint-enable @typescript-eslint/no-require-imports */
    const client = new PGlite();
    // exec() is async; PGlite queues queries behind it, so no race.
    void client.exec(SCHEMA_DDL);
    instance = drizzlePglite(client, { schema }) as unknown as Db;
    return instance;
  }
  // Vercel Fluid Compute reuses instances; keep the pool tiny per instance.
  instance = drizzle(postgres(url, { max: 5 }), { schema });
  return instance;
}

export { schema };

import { PGlite } from "@electric-sql/pglite";
import { drizzle } from "drizzle-orm/pglite";
import { SCHEMA_DDL } from "./ddl";
import * as schema from "./schema";

/**
 * An in-memory Postgres (PGlite/WASM) with the full schema applied — bun test
 * exercises real SQL against the real drizzle schema with no daemon. Not a
 * .test.ts file: it's a fixture imported by tests (and by the game server's
 * PERSISTENCE=memory mode later).
 *
 * The DDL mirrors db/schema.ts. drizzle-kit generates the production
 * migrations from the same schema module, and the auth integration test
 * exercises every table, so drift between this DDL and schema.ts fails fast.
 */
export async function createTestDb() {
  const client = new PGlite();
  await client.exec(SCHEMA_DDL);
  return drizzle(client, { schema });
}

export type TestDb = Awaited<ReturnType<typeof createTestDb>>;

"use client";

import { use, useEffect, useState } from "react";
import Link from "next/link";
import { ensureSignedIn } from "@/lib/auth/client";
import { acceptInviteToken, resolveInviteToken } from "@/lib/online/onlineClient";

/**
 * The invite-link landing page: resolves the token (so the world's name shows
 * before any sign-in), creates a guest identity if needed, accepts the
 * membership, and points at the game — where the world now sits in the
 * Online Worlds list. Deliberately unmagical: joining a friend's world is a
 * two-click story, not hidden state threading into the shell.
 */
export default function JoinPage({ params }: { params: Promise<{ token: string }> }) {
  const { token } = use(params);
  const [state, setState] = useState<{ phase: "loading" } | { phase: "joined"; worldName: string } | { phase: "error"; message: string }>({
    phase: "loading"
  });

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const invite = await resolveInviteToken(token);
      if (!invite) return void (!cancelled && setState({ phase: "error", message: "This invite link is invalid or has expired." }));
      const user = await ensureSignedIn();
      if (!user) return void (!cancelled && setState({ phase: "error", message: "Could not sign you in — try again." }));
      const accepted = await acceptInviteToken(token);
      if (!accepted) return void (!cancelled && setState({ phase: "error", message: "This invite could not be accepted (it may be used up)." }));
      if (!cancelled) setState({ phase: "joined", worldName: invite.worldName });
    })();
    return () => {
      cancelled = true;
    };
  }, [token]);

  return (
    <main className="menu-screen join-page">
      <div className="net-modal-box">
        {state.phase === "loading" && <p>Checking your invite…</p>}
        {state.phase === "error" && <p>{state.message}</p>}
        {state.phase === "joined" && (
          <>
            <p>
              You&apos;ve joined <strong>{state.worldName}</strong>!
            </p>
            <p>Open the game and press its card in Online Worlds.</p>
          </>
        )}
        <Link className="mc-button" href="/">
          {state.phase === "joined" ? "Open the game" : "Back to the game"}
        </Link>
      </div>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import MinecraftGame from "@/components/MinecraftGame";
import ProfileSelect from "@/components/menu/ProfileSelect";
import WorldSelect from "@/components/menu/WorldSelect";
import { ensureSignedIn } from "@/lib/auth/client";
import { migrateLegacySave } from "@/lib/game/legacyMigration";
import { getProfile, setActiveProfile } from "@/lib/game/profiles";
import { deleteWorld, getWorld, touchWorld, type WorldMeta } from "@/lib/game/worlds";
import { requestJoinTicket, type OnlineWorld } from "@/lib/online/onlineClient";
import { connectNetworkSession, type NetworkSession } from "@/lib/net/NetworkSession";
import { installUiTiles } from "@/lib/ui/chromeTiles";

/**
 * Top-level menu shell. Owns the screen state machine (profile-select ->
 * world-select -> play) and boots the legacy migration once on mount. The play
 * screen mounts MinecraftGame keyed by world id + a reload nonce, so switching
 * worlds (or Load/Reset) remounts the subtree — the game effect's cleanup
 * disposes the old engine/renderer and a fresh mount boots the next world, with
 * no page reload.
 */
type Screen =
  | { name: "profile-select" }
  | { name: "world-select"; profileId: string }
  | { name: "play"; profileId: string; worldId: string }
  | { name: "play-online"; profileId: string; world: OnlineWorld; session: NetworkSession };

/** Online worlds mount the same game subtree; the meta is a projection of the server row. */
function onlineWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
  return {
    id: `online:${world.id}`,
    profileId,
    name: world.name,
    seed: world.seed,
    worldType: world.worldType as WorldMeta["worldType"],
    gameMode: world.gameMode as WorldMeta["gameMode"],
    difficulty: world.difficulty as WorldMeta["difficulty"],
    hardcore: world.hardcore,
    worldgenVersion: world.worldgenVersion,
    createdAt: 0,
    lastPlayedAt: 0
  };
}

/**
 * Remembers the world being played for this tab so a reload resumes it instead
 * of dropping back to the menu. sessionStorage (not localStorage) so a brand-new
 * tab still cold-starts at profile-select.
 */
const SESSION_KEY = "monecraft_active_session";

function readSessionPointer(): { profileId: string; worldId: string } | null {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { profileId?: unknown; worldId?: unknown };
    if (typeof parsed?.profileId === "string" && typeof parsed?.worldId === "string") {
      return { profileId: parsed.profileId, worldId: parsed.worldId };
    }
    return null;
  } catch {
    return null;
  }
}

function writeSessionPointer(pointer: { profileId: string; worldId: string } | null): void {
  try {
    if (pointer) sessionStorage.setItem(SESSION_KEY, JSON.stringify(pointer));
    else sessionStorage.removeItem(SESSION_KEY);
  } catch {
    // No resume across reload if sessionStorage is unavailable — never fatal.
  }
}

export default function GameShell() {
  const [ready, setReady] = useState(false);
  const [screen, setScreen] = useState<Screen>({ name: "profile-select" });
  const [reloadNonce, setReloadNonce] = useState(0);
  const [connecting, setConnecting] = useState<string | null>(null);
  const [connectError, setConnectError] = useState<string | null>(null);

  /** Guest-or-account → ticket → socket → replica sync → play. */
  const playOnline = async (profileId: string, world: OnlineWorld) => {
    setConnectError(null);
    setConnecting(world.name);
    try {
      if (!(await ensureSignedIn())) throw new Error("sign-in failed");
      const grant = await requestJoinTicket(world.id);
      if (!grant) throw new Error("could not get a join ticket (is the game server configured?)");
      const session = await connectNetworkSession(grant.gameServerUrl, grant.ticket);
      setScreen({ name: "play-online", profileId, world, session });
    } catch (error) {
      setConnectError(error instanceof Error ? error.message : "connection failed");
    } finally {
      setConnecting(null);
    }
  };

  useEffect(() => {
    installUiTiles(); // the menu chrome shares the in-game noise tiles
    migrateLegacySave();
    // Resume the tab's world if one was being played and still exists.
    const pointer = readSessionPointer();
    const resume: Screen | null =
      pointer && getProfile(pointer.profileId) && getWorld(pointer.worldId) ? { name: "play", profileId: pointer.profileId, worldId: pointer.worldId } : null;
    // Microtask hop keeps this off the synchronous effect path (cascading-render lint).
    queueMicrotask(() => {
      if (resume) setScreen(resume);
      setReady(true);
    });
  }, []);

  // localStorage is read below; hold the neutral frame until we're client-side.
  if (!ready) return <div className="menu-screen" />;

  if (screen.name === "play") {
    const profile = getProfile(screen.profileId);
    const world = getWorld(screen.worldId);
    // Both exist in normal flow; a cross-tab delete drops us back to a menu.
    if (profile && world) {
      return (
        <MinecraftGame
          key={`${world.id}:${reloadNonce}`}
          world={world}
          profile={profile}
          onQuitToWorlds={() => {
            writeSessionPointer(null);
            setScreen({ name: "world-select", profileId: profile.id });
          }}
          onDeleteWorld={() => {
            deleteWorld(world.id); // hardcore Game Over: erase the dead world and leave
            writeSessionPointer(null);
            setScreen({ name: "world-select", profileId: profile.id });
          }}
          onReloadWorld={() => setReloadNonce((nonce) => nonce + 1)}
        />
      );
    }
  }

  if (screen.name === "play-online") {
    const profile = getProfile(screen.profileId);
    if (profile) {
      return (
        <MinecraftGame
          key={`online:${screen.world.id}`}
          world={onlineWorldMeta(screen.world, profile.id)}
          profile={profile}
          online={screen.session}
          onQuitToWorlds={() => setScreen({ name: "world-select", profileId: profile.id })}
          onDeleteWorld={() => setScreen({ name: "world-select", profileId: profile.id })}
          onReloadWorld={() => setScreen({ name: "world-select", profileId: profile.id })}
        />
      );
    }
  }

  if (screen.name === "world-select") {
    const profile = getProfile(screen.profileId);
    if (profile) {
      return (
        <>
          <WorldSelect
            profile={profile}
            onPlay={(worldId) => {
              touchWorld(worldId);
              writeSessionPointer({ profileId: profile.id, worldId });
              setScreen({ name: "play", profileId: profile.id, worldId });
            }}
            onPlayOnline={(world) => void playOnline(profile.id, world)}
            onBack={() => setScreen({ name: "profile-select" })}
          />
          {connecting && (
            <div className="net-modal" role="status">
              <div className="net-modal-box">Joining “{connecting}”…</div>
            </div>
          )}
          {connectError && (
            <div className="net-modal" role="alertdialog" aria-label="Connection failed">
              <div className="net-modal-box">
                <p>Couldn&apos;t join: {connectError}</p>
                <button type="button" className="mc-button" onClick={() => setConnectError(null)}>
                  OK
                </button>
              </div>
            </div>
          )}
        </>
      );
    }
  }

  return (
    <ProfileSelect
      onPlay={(profileId) => {
        setActiveProfile(profileId);
        setScreen({ name: "world-select", profileId });
      }}
    />
  );
}

import { useCallback, useEffect, useState } from "react";
import CreateWorldForm from "@/components/menu/CreateWorldForm";
import MenuScreen from "@/components/menu/MenuScreen";
import type { Profile } from "@/lib/game/profiles";
import { GAME_MODE_PRESETS, type GameMode } from "@/lib/game/gameModes";
import { DIFFICULTY_PRESETS, type Difficulty } from "@/lib/game/difficulties";
import { createWorld, deleteWorld, MAX_WORLD_NAME, renameWorld, WORLD_TYPE_PRESETS, worldsForProfile } from "@/lib/game/worlds";
import type { WorldType } from "@/lib/world";
import { onlineUsed } from "@/lib/auth/client";
import { createInviteLink, createOnlineWorld, listOnlineWorlds, type OnlineWorld } from "@/lib/online/onlineClient";
import { resolveSeed } from "@/lib/game/worlds";

/** Short label for a world type (the default type is left unlabelled on cards). */
function worldTypeLabel(id: WorldType): string {
  return WORLD_TYPE_PRESETS.find((preset) => preset.id === id)?.label ?? id;
}

/** Short label for a game mode (survival is left unlabelled on cards). */
function gameModeLabel(id: GameMode): string {
  return GAME_MODE_PRESETS.find((preset) => preset.id === id)?.label ?? id;
}

/** Short label for a difficulty (normal is left unlabelled on cards). */
function difficultyLabel(id: Difficulty): string {
  return DIFFICULTY_PRESETS.find((preset) => preset.id === id)?.label ?? id;
}

type WorldSelectProps = {
  profile: Profile;
  /** Enter a world (the shell records last-played and boots it). */
  onPlay: (worldId: string) => void;
  /** Join an online (server-hosted) world. */
  onPlayOnline: (world: OnlineWorld) => void;
  /** Back to the profile list. */
  onBack: () => void;
};

/** A profile's world list: pick a world, or create / rename / delete one. */
export default function WorldSelect({ profile, onPlay, onPlayOnline, onBack }: WorldSelectProps) {
  const [creating, setCreating] = useState(false);
  const [creatingOnline, setCreatingOnline] = useState(false);
  const [onlineWorlds, setOnlineWorlds] = useState<OnlineWorld[] | null>(null);
  const [inviteCopied, setInviteCopied] = useState<string | null>(null);

  // Online worlds appear only once this browser has used online features —
  // offline-first: no fetch, no section, no account until the player opts in.
  const refreshOnline = useCallback(() => {
    if (onlineUsed()) void listOnlineWorlds().then(setOnlineWorlds);
  }, []);
  useEffect(() => refreshOnline(), [refreshOnline]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null);

  if (creating) {
    return (
      <MenuScreen title={`${profile.name} — New World`}>
        <CreateWorldForm
          onCreate={(name, seed, worldType, gameMode, difficulty, hardcore) => {
            const world = createWorld(profile.id, name, seed, { worldType, gameMode, difficulty, hardcore });
            setCreating(false);
            onPlay(world.id); // straight into the freshly created world
          }}
          onCancel={() => setCreating(false)}
        />
      </MenuScreen>
    );
  }

  if (creatingOnline) {
    return (
      <MenuScreen title={`${profile.name} — New Online World`}>
        <CreateWorldForm
          onCreate={(name, seed, worldType, gameMode, difficulty, hardcore) => {
            // Same form, different home: the world row lives on the server and
            // the game server hosts it — friends join by invite link.
            void createOnlineWorld({ name, seed: resolveSeed(seed), worldType, gameMode, difficulty, hardcore }).then((world) => {
              setCreatingOnline(false);
              if (world) onPlayOnline(world);
            });
          }}
          onCancel={() => setCreatingOnline(false)}
        />
      </MenuScreen>
    );
  }

  const worlds = worldsForProfile(profile.id);

  return (
    <MenuScreen title={`${profile.name} — Worlds`}>
      {worlds.length === 0 ? (
        <p className="menu-empty">No worlds yet. Create your first world.</p>
      ) : (
        <ul className="menu-list">
          {worlds.map((world) => (
            <li key={world.id} className="menu-card">
              {editingId === world.id ? (
                <form
                  className="menu-rename"
                  onSubmit={(event) => {
                    event.preventDefault();
                    renameWorld(world.id, editName);
                    setEditingId(null); // re-render re-reads the manifest
                  }}
                >
                  <input
                    className="menu-input"
                    value={editName}
                    maxLength={MAX_WORLD_NAME}
                    autoFocus
                    aria-label="Rename world"
                    onChange={(event) => setEditName(event.target.value)}
                  />
                  <button type="submit" className="mc-button">
                    Save
                  </button>
                  <button type="button" className="mc-button" onClick={() => setEditingId(null)}>
                    Cancel
                  </button>
                </form>
              ) : confirmingDeleteId === world.id ? (
                <div className="menu-confirm">
                  <span>Delete “{world.name}”? This cannot be undone.</span>
                  <div className="menu-confirm-actions">
                    <button
                      className="mc-button danger"
                      onClick={() => {
                        deleteWorld(world.id);
                        setConfirmingDeleteId(null); // re-render re-reads the manifest
                      }}
                    >
                      Delete
                    </button>
                    <button className="mc-button" onClick={() => setConfirmingDeleteId(null)}>
                      Cancel
                    </button>
                  </div>
                </div>
              ) : (
                <>
                  <button className="menu-card-play" data-testid={`world-${world.id}`} onClick={() => onPlay(world.id)}>
                    <span className="menu-card-name">{world.name}</span>
                    <span className="menu-card-sub">
                      {world.hardcore ? `Hardcore · ` : ""}
                      {world.gameMode !== "survival" ? `${gameModeLabel(world.gameMode)} · ` : ""}
                      {!world.hardcore && world.difficulty !== "normal" ? `${difficultyLabel(world.difficulty)} · ` : ""}
                      {world.worldType !== "default" ? `${worldTypeLabel(world.worldType)} · ` : ""}Seed {world.seed}
                    </span>
                  </button>
                  <div className="menu-card-actions">
                    <button
                      className="mc-button"
                      onClick={() => {
                        setEditName(world.name);
                        setEditingId(world.id);
                      }}
                    >
                      Rename
                    </button>
                    <button className="mc-button" onClick={() => setConfirmingDeleteId(world.id)}>
                      Delete
                    </button>
                  </div>
                </>
              )}
            </li>
          ))}
        </ul>
      )}
      {onlineWorlds !== null && (
        <section className="menu-online">
          <h3 className="menu-online-title">Online Worlds</h3>
          {onlineWorlds.length === 0 ? (
            <p className="menu-empty">No online worlds yet — create one and share the invite link.</p>
          ) : (
            <ul className="menu-list">
              {onlineWorlds.map((world) => (
                <li key={world.id} className="menu-card">
                  <button className="menu-card-play" data-testid={`online-world-${world.id}`} onClick={() => onPlayOnline(world)}>
                    <span className="menu-card-name">{world.name}</span>
                    <span className="menu-card-sub">
                      {world.role === "owner" ? "Your world" : "Joined"} · Seed {world.seed}
                    </span>
                  </button>
                  {world.role === "owner" && (
                    <div className="menu-card-actions">
                      <button
                        className="mc-button"
                        onClick={() => {
                          void createInviteLink(world.id).then((link) => {
                            if (!link) return;
                            void navigator.clipboard?.writeText(link).catch(() => {});
                            setInviteCopied(world.id);
                          });
                        }}
                      >
                        {inviteCopied === world.id ? "Link copied!" : "Copy invite"}
                      </button>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          )}
          <button className="mc-button" data-testid="new-online-world" onClick={() => setCreatingOnline(true)}>
            New Online World
          </button>
        </section>
      )}
      <div className="menu-bottom-row">
        <button className="mc-button" data-testid="back-to-profiles" onClick={onBack}>
          Back
        </button>
        <button className="mc-button menu-primary" data-testid="new-world" onClick={() => setCreating(true)}>
          New World
        </button>
      </div>
    </MenuScreen>
  );
}

