3	import { useEffect, useState } from "react";
4	import { authClient, currentUser, ensureSignedIn, markOnlineUsed, onlineUsed, type OnlineUser } from "@/lib/auth/client";
5	
6	/**
7	 * The account corner of the menu: shows who you are online, offers instant
8	 * guest play, and upgrades a guest to a real account without losing worlds
9	 * (the server re-parents them — see lib/auth/server.ts). Purely additive to
10	 * the offline game: with no online features touched, no account ever exists.
11	 */
12	export default function AccountPanel() {
13	  const [user, setUser] = useState<OnlineUser | null>(null);
14	  const [mode, setMode] = useState<"closed" | "signin" | "signup">("closed");
15	  const [email, setEmail] = useState("");
16	  const [password, setPassword] = useState("");
17	  const [name, setName] = useState("");
18	  const [busy, setBusy] = useState(false);
19	  const [error, setError] = useState<string | null>(null);
20	
21	  useEffect(() => {
22	    // Offline-first: never even ask the server about a session until this
23	    // browser has used online features once (see lib/auth/client.ts).
24	    if (onlineUsed()) void currentUser().then(setUser);
25	  }, []);
26	
27	  const refresh = async () => setUser(await currentUser());
28	
29	  const submit = async (event: React.FormEvent) => {
30	    event.preventDefault();
31	    setBusy(true);
32	    setError(null);
33	    markOnlineUsed();
34	    // Sign-up (and sign-in) while holding a guest session links the account:
35	    // the guest's worlds move over server-side before the guest is deleted.
36	    const result =
37	      mode === "signup"
38	        ? await authClient().signUp.email({ email, password, name: name.trim() || email.split("@")[0] })
39	        : await authClient().signIn.email({ email, password });
40	    setBusy(false);
41	    if (result.error) {
42	      setError(result.error.message ?? "That didn't work — check the details and try again.");
43	      return;
44	    }
45	    setMode("closed");
46	    setPassword("");
47	    await refresh();
48	  };
49	
50	  if (mode !== "closed") {
51	    return (
52	      <form className="menu-form account-panel" onSubmit={submit}>
53	        <label className="menu-field">
54	          Email
55	          <input className="menu-input" type="email" required value={email} onChange={(e) => setEmail(e.target.value)} />
56	        </label>
57	        {mode === "signup" && (
58	          <label className="menu-field">
59	            Display name
60	            <input className="menu-input" value={name} maxLength={24} onChange={(e) => setName(e.target.value)} />
61	          </label>
62	        )}
63	        <label className="menu-field">
64	          Password
65	          <input className="menu-input" type="password" required minLength={8} value={password} onChange={(e) => setPassword(e.target.value)} />
66	        </label>
67	        {error && <div className="account-error">{error}</div>}
68	        <div className="menu-form-actions">
69	          <button type="submit" className="mc-button" disabled={busy}>
70	            {mode === "signup" ? (user?.isAnonymous ? "Create account (keeps your worlds)" : "Create account") : "Sign in"}
71	          </button>
72	          <button type="button" className="mc-button" onClick={() => setMode(mode === "signup" ? "signin" : "signup")}>
73	            {mode === "signup" ? "I have an account" : "I need an account"}
74	          </button>
75	          <button type="button" className="mc-button" onClick={() => setMode("closed")}>
76	            Cancel
77	          </button>
78	        </div>
79	      </form>
80	    );
81	  }
82	
83	  return (
84	    <div className="account-panel">
85	      {user ? (
86	        <>
87	          <span className="account-status">{user.isAnonymous ? "Playing as guest" : `Signed in as ${user.name}`}</span>
88	          {user.isAnonymous ? (
89	            <button type="button" className="mc-button" onClick={() => setMode("signup")}>
90	              Keep my worlds — create account
91	            </button>
92	          ) : (
93	            <button
94	              type="button"
95	              className="mc-button"
96	              onClick={async () => {
97	                await authClient().signOut();
98	                await refresh();
99	              }}
100	            >
101	              Sign out
102	            </button>
103	          )}
104	        </>
105	      ) : (
106	        <>
107	          <span className="account-status">Offline</span>
108	          <button
109	            type="button"
110	            className="mc-button"
111	            onClick={async () => {
112	              setBusy(true);
113	              await ensureSignedIn();
114	              setBusy(false);
115	              await refresh();
116	            }}
117	            disabled={busy}
118	          >
119	            Play online as guest
120	          </button>
121	          <button type="button" className="mc-button" onClick={() => setMode("signin")}>
122	            Sign in
123	          </button>
124	        </>
125	      )}
126	    </div>
127	  );
128	}
