1	import { useState } from "react";
2	import PixelImg from "@/components/game/PixelImg";
3	import AccountPanel from "@/components/menu/AccountPanel";
4	import CreateProfileForm from "@/components/menu/CreateProfileForm";
5	import MenuScreen from "@/components/menu/MenuScreen";
6	import { createProfile, deleteProfile, MAX_PROFILE_NAME, readProfiles, renameProfile } from "@/lib/game/profiles";
7	import { skinPortraitUrl } from "@/lib/ui/sprites";
8	import { deleteWorldsForProfile, worldsForProfile } from "@/lib/game/worlds";
9	
10	type ProfileSelectProps = {
11	  /** Enter a profile: select it and show its worlds. */
12	  onPlay: (profileId: string) => void;
13	};
14	
15	/** The top menu: pick a player profile, or create / rename / delete one. */
16	export default function ProfileSelect({ onPlay }: ProfileSelectProps) {
17	  const [creating, setCreating] = useState(false);
18	  const [editingId, setEditingId] = useState<string | null>(null);
19	  const [editName, setEditName] = useState("");
20	  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null);
21	
22	  const { profiles } = readProfiles();
23	  // With no profiles (first run, or the last one was just deleted) there is
24	  // nothing to select, so open straight into the create form with no Cancel.
25	  const firstRun = profiles.length === 0;
26	
27	  if (creating || firstRun) {
28	    return (
29	      <MenuScreen title={firstRun ? "Create Your Profile" : "New Profile"}>
30	        <CreateProfileForm
31	          onCreate={(name, skinId) => {
32	            const profile = createProfile(name, skinId);
33	            setCreating(false);
34	            onPlay(profile.id); // straight into the new profile's (empty) world list
35	          }}
36	          onCancel={firstRun ? undefined : () => setCreating(false)}
37	        />
38	      </MenuScreen>
39	    );
40	  }
41	
42	  return (
43	    <MenuScreen title="Select Profile">
44	      <AccountPanel />
45	      <ul className="menu-list">
46	        {profiles.map((profile) => (
47	          <li key={profile.id} className="menu-card">
48	            {editingId === profile.id ? (
49	              <form
50	                className="menu-rename"
51	                onSubmit={(event) => {
52	                  event.preventDefault();
53	                  renameProfile(profile.id, editName);
54	                  setEditingId(null); // re-render re-reads the manifest
55	                }}
56	              >
57	                <input
58	                  className="menu-input"
59	                  value={editName}
60	                  maxLength={MAX_PROFILE_NAME}
61	                  autoFocus
62	                  aria-label="Rename profile"
63	                  onChange={(event) => setEditName(event.target.value)}
64	                />
65	                <button type="submit" className="mc-button">
66	                  Save
67	                </button>
68	                <button type="button" className="mc-button" onClick={() => setEditingId(null)}>
69	                  Cancel
70	                </button>
71	              </form>
72	            ) : confirmingDeleteId === profile.id ? (
73	              <div className="menu-confirm">
74	                <span>Delete “{profile.name}” and all its worlds?</span>
75	                <div className="menu-confirm-actions">
76	                  <button
77	                    className="mc-button danger"
78	                    onClick={() => {
79	                      deleteWorldsForProfile(profile.id);
80	                      deleteProfile(profile.id);
81	                      setConfirmingDeleteId(null); // re-render re-reads the manifest
82	                    }}
83	                  >
84	                    Delete
85	                  </button>
86	                  <button className="mc-button" onClick={() => setConfirmingDeleteId(null)}>
87	                    Cancel
88	                  </button>
89	                </div>
90	              </div>
91	            ) : (
92	              <>
93	                <button className="menu-card-play" data-testid={`profile-${profile.id}`} onClick={() => onPlay(profile.id)}>
94	                  <PixelImg src={skinPortraitUrl(profile.skinId)} alt="" size={40} aria-hidden />
95	                  <span className="menu-card-name">{profile.name}</span>
96	                  <span className="menu-card-sub">{worldsForProfile(profile.id).length} worlds</span>
97	                </button>
98	                <div className="menu-card-actions">
99	                  <button
100	                    className="mc-button"
101	                    onClick={() => {
102	                      setEditName(profile.name);
103	                      setEditingId(profile.id);
104	                    }}
105	                  >
106	                    Rename
107	                  </button>
108	                  <button className="mc-button" onClick={() => setConfirmingDeleteId(profile.id)}>
109	                    Delete
110	                  </button>
111	                </div>
112	              </>
113	            )}
114	          </li>
115	        ))}
116	      </ul>
117	      <button className="mc-button menu-primary" data-testid="new-profile" onClick={() => setCreating(true)}>
118	        New Profile
119	      </button>
120	    </MenuScreen>
121	  );
122	}
