13	import type { PlayerState } from "@/lib/game/engine/state";
14	import { encodeServerMessage, gzipWorldSync } from "@/lib/net/codec";
15	import {
16	  CLOSE_KICKED,
17	  CLOSE_ROOM_FULL,
18	  CLOSE_SERVER_SHUTDOWN,
19	  CLOSE_SLOW_CLIENT,
20	  PROTOCOL_VERSION,
21	  ROOM_CAPACITY,
