1	import type { Command } from "@/lib/game/engine/commands";
2	import type { GameEvent } from "@/lib/game/engine/state";
3	import type { SavedContainer, SavedMob, SavedPlayer, SavedVehicle } from "@/lib/game/types";
4	
5	/**
6	 * The client↔game-server wire protocol. Versioned as a whole: a client built
7	 * against a different PROTOCOL_VERSION is refused at the door (its join
8	 * ticket carries the number), so mid-session format drift can't happen.
9	 *
10	 * v1 is JSON envelopes discriminated on `t`, except the one big payload —
11	 * the join world-sync — which travels as a gzipped binary frame (see
12	 * codec.ts). The envelope layout deliberately leaves room to move the hot
13	 * paths (pose/tick) to packed binary later without renegotiating anything.
14	 *
15	 * Validation is hand-rolled and TOTAL (the save.ts house style): the server
16	 * feeds hostile bytes through these readers and gets a typed message or
17	 * null — never an exception, never a partially-checked object.
18	 */
19	export const PROTOCOL_VERSION = 1;
20	
21	// ── close codes (WebSocket application range) ────────────────────────────────
22	export const CLOSE_BAD_TICKET = 4000;
23	export const CLOSE_PROTOCOL_MISMATCH = 4001;
24	export const CLOSE_ROOM_FULL = 4002;
25	export const CLOSE_KICKED = 4003;
26	export const CLOSE_IDLE_TIMEOUT = 4004;
27	export const CLOSE_SERVER_SHUTDOWN = 4005;
28	export const CLOSE_SLOW_CLIENT = 4008;
29	
30	/** Max players per room (the v1 co-op scale the whole design assumes). */
31	export const ROOM_CAPACITY = 8;
32	
33	// ── client → server ──────────────────────────────────────────────────────────
34	
35	/** First frame on the socket: the join ticket (minted by the web API) + the client's protocol. */
36	export type HelloMessage = { t: "hello"; ticket: string; protocol: number };
37	
38	/** The client-authoritative avatar pose, streamed at tick rate. */
39	export type PoseMessage = {
40	  t: "pose";
41	  seq: number;
42	  x: number;
43	  y: number;
44	  z: number;
45	  yaw: number;
46	  pitch: number;
47	  onGround: boolean;
48	  /** The player's live movement intents (server systems read them for vehicles etc.). */
49	  move: { forward: boolean; back: boolean; left: boolean; right: boolean; jump: boolean; sprint: boolean; crouch: boolean };
50	  mineHeld: boolean;
51	};
52	
53	/**
54	 * A discrete command. Carries the client's claimed eye pose at click time:
55	 * the server applies it (sanity-checked like any pose) before dispatch, so
56	 * aimed raycasts (attack/placeBlock) resolve against the server's world from
57	 * where the client actually looked.
58	 */
59	export type CmdMessage = { t: "cmd"; seq: number; cmd: Command; pose: { x: number; y: number; z: number; yaw: number; pitch: number } };
60	
61	export type ChatMessage = { t: "chat"; text: string };
62	export type PingMessage = { t: "ping"; id: number; tMs: number };
63	/** Ask for a fresh world-sync + mob keyframe (reconnect resume). */
64	export type ResyncMessage = { t: "resync" };
65	
66	export type ClientMessage = HelloMessage | PoseMessage | CmdMessage | ChatMessage | PingMessage | ResyncMessage;
67	
68	// ── server → client ──────────────────────────────────────────────────────────
69	
70	export type RosterEntry = { id: string; name: string; skinId: string | null; x: number; y: number; z: number; yaw: number };
71	
72	export type WelcomeMessage = {
73	  t: "welcome";
74	  protocol: number;
75	  playerId: string;
76	  worldId: string;
77	  seed: number;
78	  worldType: string;
79	  difficulty: string;
80	  hardcore: boolean;
81	  dayClock: number;
82	  tick: number;
83	  players: RosterEntry[];
84	};
85	
86	/**
87	 * The join payload (sent as ONE gzipped binary frame right after welcome):
88	 * everything a client can't regenerate from the seed. Mirrors the v17 save's
89	 * world half plus the live session entities.
90	 */
91	export type WorldSync = {
92	  t: "worldSync";
93	  tick: number;
94	  dayClock: number;
95	  changes: Array<[number, number]>;
96	  blockEntities: SavedContainer[];
97	  lootedChests: number[];
98	  mobs: SavedMob[];
99	  liveMobs: MobPose[];
100	  vehicles: SavedVehicle[];
101	  players: RosterEntry[];
102	};
103	
104	/** One mob's replicated pose (10 Hz, deadbanded; keyframed every ~5s). */
105	export type MobPose = { id: number; kind: string; hostile: boolean; x: number; y: number; z: number; yaw: number; hp: number; moveSpeed: number };
106	
107	/** One player's replicated pose (20 Hz). */
108	export type PlayerPose = { id: string; x: number; y: number; z: number; yaw: number; pitch: number };
109	
110	/**
111	 * The per-player private delta: the server-authoritative mirror of what the
112	 * SP snapshot shows about YOU. Only changed fields are present.
113	 */
114	export type SelfDelta = {
115	  inventorySlots?: SavedPlayer["inventorySlots"];
116	  equippedArmor?: SavedPlayer["equippedArmor"];
117	  selectedSlot?: number;
118	  hearts?: number;
119	  hunger?: number;
120	  oxygen?: number;
121	  xp?: number;
122	  effects?: SavedPlayer["effects"];
123	  isDead?: boolean;
124	  respawnSeconds?: number;
125	  gameMode?: string;
126	  sleeping?: boolean;
127	};
128	
129	export type TickMessage = {
130	  t: "tick";
131	  n: number;
132	  /** Block writes this tick as [voxelIndex, blockId] — the replica's world mutation channel. */
133	  blocks?: Array<[number, number]>;
134	  /** Attributed world events since the last tick (block edits ride these). */
135	  ev: Array<GameEvent & { playerId?: string }>;
136	  /** Other players' poses (the recipient's own is omitted). */
137	  pp: PlayerPose[];
138	  /** Mob poses that moved past the deadband this window (10 Hz). */
139	  mp: MobPose[];
140	  /** Day clock, every ~20 ticks (clients advance it locally in between). */
141	  day?: number;
142	  /** The recipient's private state changes. */
143	  self?: SelfDelta;
144	};
145	
146	export type MobsKeyframeMessage = { t: "mobsKeyframe"; n: number; mobs: MobPose[] };
147	export type PlayerJoinedMessage = { t: "playerJoined"; player: RosterEntry };
148	export type PlayerLeftMessage = { t: "playerLeft"; id: string };
149	export type ContainerMessage = { t: "container"; index: number; slots: SavedContainer["slots"] };
150	export type ChatBroadcastMessage = { t: "chat"; from: string; name: string; text: string };
151	export type PongMessage = { t: "pong"; id: number; tMs: number; serverTick: number };
152	/** Position correction: the client must snap its avatar here (failed pose sanity check). */
153	export type ForcePoseMessage = { t: "forcePose"; x: number; y: number; z: number; yaw: number; pitch: number };
154	
155	export type ServerMessage =
156	  | WelcomeMessage
157	  | TickMessage
158	  | MobsKeyframeMessage
159	  | PlayerJoinedMessage
160	  | PlayerLeftMessage
161	  | ContainerMessage
162	  | ChatBroadcastMessage
163	  | PongMessage
164	  | ForcePoseMessage;
165	
166	// ── validators (client → server only: the server is the hostile-input side) ──
167	
168	const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
169	const isBool = (v: unknown): v is boolean => typeof v === "boolean";
170	const isStr = (v: unknown): v is string => typeof v === "string";
171	
172	function readMove(v: unknown): PoseMessage["move"] | null {
173	  if (!v || typeof v !== "object") return null;
174	  const m = v as Record<string, unknown>;
175	  const keys = ["forward", "back", "left", "right", "jump", "sprint", "crouch"] as const;
176	  const out = {} as Record<(typeof keys)[number], boolean>;
177	  for (const key of keys) {
178	    if (!isBool(m[key])) return null;
179	    out[key] = m[key] as boolean;
180	  }
181	  return out;
182	}
183	
184	function readEyePose(v: unknown): CmdMessage["pose"] | null {
185	  if (!v || typeof v !== "object") return null;
186	  const p = v as Record<string, unknown>;
187	  if (!isNum(p.x) || !isNum(p.y) || !isNum(p.z) || !isNum(p.yaw) || !isNum(p.pitch)) return null;
188	  return { x: p.x, y: p.y, z: p.z, yaw: p.yaw, pitch: p.pitch };
189	}
190	
191	/**
192	 * Command allow-list: every dispatchable type with per-field checks. Unknown
193	 * or malformed commands are dropped here — dispatch never sees them. Local-
194	 * presentation commands (pause/debug/camera) are deliberately absent: they
195	 * have no business on a wire.
196	 */
197	export function readCommand(v: unknown): Command | null {
198	  if (!v || typeof v !== "object") return null;
199	  const c = v as Record<string, unknown>;
200	  switch (c.type) {
201	    case "selectSlot":
202	      return isNum(c.index) ? { type: "selectSlot", index: Math.floor(c.index) } : null;
203	    case "craft":
204	      return isStr(c.recipeId) ? { type: "craft", recipeId: c.recipeId } : null;
205	    case "swapSlots":
206	      return isNum(c.from) && isNum(c.to) ? { type: "swapSlots", from: Math.floor(c.from), to: Math.floor(c.to) } : null;
207	    case "moveStack":
208	      return isNum(c.from) && isNum(c.to) ? { type: "moveStack", from: Math.floor(c.from), to: Math.floor(c.to) } : null;
209	    case "toggleEquipArmor":
210	      return isNum(c.index) ? { type: "toggleEquipArmor", index: Math.floor(c.index) } : null;
211	    case "unequipArmor":
212	      return c.slot === "helmet" || c.slot === "chestplate" || c.slot === "leggings" || c.slot === "boots" ? { type: "unequipArmor", slot: c.slot } : null;
213	    case "anvilRename":
214	      return isStr(c.name) ? { type: "anvilRename", name: c.name.slice(0, 64) } : null;
215	    case "enchant":
216	      return isStr(c.enchant) ? ({ type: "enchant", enchant: c.enchant } as Command) : null;
217	    case "creativeGiveItem":
218	      return isStr(c.itemId) ? { type: "creativeGiveItem", itemId: c.itemId } : null;
219	    case "setGameMode":
220	      return isStr(c.mode) ? ({ type: "setGameMode", mode: c.mode } as Command) : null;
221	    case "setDifficulty":
222	      return isStr(c.difficulty) ? ({ type: "setDifficulty", difficulty: c.difficulty } as Command) : null;
223	    case "toggleInventory":
224	    case "toggleAdvancements":
225	    case "eatFood":
226	    case "drinkPotion":
227	    case "anvilCombine":
228	    case "anvilRepair":
229	    case "grindstoneStrip":
230	    case "placeBlock":
231	    case "attack":
232	    case "toggleFlight":
233	    case "unstuck":
234	    case "respawn":
235	    case "dismissVictory":
236	    case "wakeUp":
237	      return { type: c.type } as Command;
238	    default:
239	      return null;
240	  }
241	}
242	
243	/** Parses one client frame (already JSON.parsed). Total: null for anything off-spec. */
244	export function readClientMessage(v: unknown): ClientMessage | null {
245	  if (!v || typeof v !== "object") return null;
246	  const m = v as Record<string, unknown>;
247	  switch (m.t) {
248	    case "hello":
249	      return isStr(m.ticket) && isNum(m.protocol) ? { t: "hello", ticket: m.ticket, protocol: m.protocol } : null;
250	    case "pose": {
