/** One validated client frame. */
async handleMessage(playerId: string, message: ClientMessage): Promise<void> {
  const conn = this.clients.get(playerId);
  if (!conn) return;
  switch (message.t) {
    case "pose": {
      if (message.seq <= conn.poseSeq) return; // stale or replayed
      conn.poseSeq = message.seq;
      const elapsed = Math.max(1, this.tickCount - conn.lastPoseTick) * TICK_SECONDS;
      const { accepted } = this.engine.applyRemotePose(playerId, message, elapsed);
      this.engine.setPlayerInput(playerId, { move: message.move, mineHeld: message.mineHeld });
      if (accepted) {
        conn.lastPoseTick = this.tickCount;
      } else {
        const player = this.engine.state.players.get(playerId);
        if (player) {
          conn.sink.send(
            encodeServerMessage({
              t: "forcePose",
              x: player.position.x,
              y: player.position.y,
              z: player.position.z,
              yaw: player.yaw,
              pitch: player.pitch
            })
          );
        }
      }
      return;
    }
    case "cmd": {
      if (conn.budget.cmd >= 60) return; // per-second flood guard
      conn.budget.cmd += 1;
      // Apply the claimed eye pose (same clamps as the stream) so the
      // command's raycast happens from where the client actually aimed.
      const elapsed = Math.max(1, this.tickCount - conn.lastPoseTick) * TICK_SECONDS;
      this.engine.applyRemotePose(playerId, { ...message.pose, onGround: this.engine.state.players.get(playerId)?.onGround ?? false }, elapsed);
      this.recordLog({ tick: this.tickCount, playerId, cmd: message.cmd, pose: message.pose });
      this.engine.dispatch(message.cmd, playerId);
      return;

