"use client";

import type { WorldSummary } from "@/lib/online/worldsService";

/**
 * Browser-side fetch helpers for the online worlds API. Thin and total:
 * failures come back as null/false, never exceptions — the menu shows
 * "offline" states instead of crashing.
 */

export type OnlineWorld = WorldSummary;

export async function listOnlineWorlds(): Promise<OnlineWorld[] | null> {
  try {
    const response = await fetch("/api/worlds");
    if (!response.ok) return null;
    const { worlds } = (await response.json()) as { worlds: OnlineWorld[] };
    return worlds;
  } catch {
    return null;
  }
}

export async function createOnlineWorld(input: {
  name: string;
  seed: number;
  worldType: string;
  gameMode: string;
  difficulty: string;
  hardcore: boolean;
}): Promise<OnlineWorld | null> {
  try {
    const response = await fetch("/api/worlds", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ ...input, kind: "mp" })
    });
    if (!response.ok) return null;
    const { world } = (await response.json()) as { world: OnlineWorld };
    return world;
  } catch {
    return null;
  }
}

/** Mints an invite token and returns the full shareable link. */
export async function createInviteLink(worldId: string): Promise<string | null> {
  try {
    const response = await fetch(`/api/worlds/${worldId}/invites`, { method: "POST" });
    if (!response.ok) return null;
    const { token } = (await response.json()) as { token: string };
    return `${window.location.origin}/join/${token}`;
  } catch {
    return null;
  }
}

/** Revokes every outstanding invite link for a world (owner only). Returns the count, or null on failure. */
export async function revokeInviteLinks(worldId: string): Promise<number | null> {
  try {
    const response = await fetch(`/api/worlds/${worldId}/invites`, { method: "DELETE" });
    if (!response.ok) return null;
    const { revoked } = (await response.json()) as { revoked: number };
    return revoked;
  } catch {
    return null;
  }
}

export async function resolveInviteToken(token: string): Promise<{ worldId: string; worldName: string } | null> {
  try {
    const response = await fetch(`/api/invite/${token}`);
    if (!response.ok) return null;
    return (await response.json()) as { worldId: string; worldName: string };
  } catch {
    return null;
  }
}

export async function acceptInviteToken(token: string): Promise<boolean> {
  try {
    const response = await fetch(`/api/invite/${token}`, { method: "POST" });
    return response.ok;
  } catch {
    return false;
  }
}

/** The join ticket + where to connect. Null covers "not a member" and misconfiguration alike. */
export async function requestJoinTicket(worldId: string): Promise<{ ticket: string; gameServerUrl: string } | null> {
  try {
    const response = await fetch(`/api/worlds/${worldId}/ticket`, { method: "POST" });
    if (!response.ok) return null;
    const { ticket, gameServerUrl } = (await response.json()) as { ticket: string; gameServerUrl: string | null };
    if (!gameServerUrl) return null;
    return { ticket, gameServerUrl };
  } catch {
    return null;
  }
}

"use client";

import { useEffect, useState } from "react";
import MinecraftGame from "@/components/MinecraftGame";
import ProfileSelect from "@/components/menu/ProfileSelect";
import WorldSelect from "@/components/menu/WorldSelect";
import { ensureSignedIn } from "@/lib/auth/client";
import { migrateLegacySave } from "@/lib/game/legacyMigration";
import { getProfile, setActiveProfile } from "@/lib/game/profiles";
import { deleteWorld, getWorld, touchWorld, type WorldMeta } from "@/lib/game/worlds";
import { requestJoinTicket, type OnlineWorld } from "@/lib/online/onlineClient";
import { connectNetworkSession, type NetworkSession } from "@/lib/net/NetworkSession";
import { installUiTiles } from "@/lib/ui/chromeTiles";

/**
 * Top-level menu shell. Owns the screen state machine (profile-select ->
 * world-select -> play) and boots the legacy migration once on mount. The play
 * screen mounts MinecraftGame keyed by world id + a reload nonce, so switching
 * worlds (or Load/Reset) remounts the subtree — the game effect's cleanup
 * disposes the old engine/renderer and a fresh mount boots the next world, with
 * no page reload.
 */
type Screen =
  | { name: "profile-select" }
  | { name: "world-select"; profileId: string }
  | { name: "play"; profileId: string; worldId: string }
  | { name: "play-online"; profileId: string; world: OnlineWorld; session: NetworkSession };

/** Online worlds mount the same game subtree; the meta is a projection of the server row. */
function onlineWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
  return {
    id: `online:${world.id}`,
    profileId,
    name: world.name,
    seed: world.seed,
    worldType: world.worldType as WorldMeta["worldType"],
    gameMode: world.gameMode as WorldMeta["gameMode"],
    difficulty: world.difficulty as WorldMeta["difficulty"],
    hardcore: world.hardcore,
    worldgenVersion: world.worldgenVersion,
    createdAt: 0,
    lastPlayedAt: 0
  };
}

